'use strict';

const S={auth:null,csrf:'',people:[],branches:[],users:[],comments:[],settings:{},audit:[],recentAudit:[],galleryAlbums:[],galleryPhotos:[],galleryVideos:[],contacts:[],contributions:[],contributionYears:[],contributionSummary:{},news:[],newsYears:[],editNewsId:null,selectedGalleryAlbumId:null,editGalleryAlbumId:null,editGalleryPhotoId:null,editGalleryVideoId:null,editContactId:null,editContributionId:null,editPersonId:null,editBranchId:null,editUserId:null,peoplePage:1,branchesPage:1,contributionsPage:1,newsPage:1,commentsPage:1,usersPage:1,auditPage:1,recentPage:1,galleryPhotoPage:1,galleryVideoPage:1,peoplePageSize:100,adminPageSize:100,galleryPhotoPageSize:100,galleryVideoPageSize:100};
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function uploadAssetUrl(value){const parts=String(value||'').replace(/\\/g,'/').split('/').filter(Boolean);return parts.length?'/uploads/'+parts.map(encodeURIComponent).join('/'):'';}
window.addEventListener('DOMContentLoaded',init);

async function init(){if('scrollRestoration' in history)history.scrollRestoration='manual';window.scrollTo(0,0);bind();await bootstrap();window.scrollTo(0,0);}
function bind(){
  $('#loginForm').addEventListener('submit',login);$('#logoutBtn').addEventListener('click',logout);$('#changePasswordBtn').addEventListener('click',()=>openModal('passwordModal'));$('#passwordForm').addEventListener('submit',changePassword);
  $$('.nav-btn').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));$$('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.closeModal)));
  $('#addPersonBtn').addEventListener('click',()=>openPerson());$('#quickAdd').addEventListener('click',()=>{switchView('people');openPerson();});$('#personForm').addEventListener('submit',savePerson);$('#peopleSearch').addEventListener('input',()=>{S.peoplePage=1;renderPeople();});$('#peoplePrivacy').addEventListener('change',()=>{S.peoplePage=1;renderPeople();});
  $('#addBranchBtn').addEventListener('click',()=>openBranch());$('#branchForm').addEventListener('submit',saveBranch);
  $('#addContributionBtn')?.addEventListener('click',()=>openContribution());$('#contributionForm')?.addEventListener('submit',saveContribution);$('#contributionSearch')?.addEventListener('input',()=>{S.contributionsPage=1;renderContributions();});$('#contributionYear')?.addEventListener('change',()=>{S.contributionsPage=1;renderContributions();});$('#contributionSort')?.addEventListener('change',()=>{S.contributionsPage=1;renderContributions();});
  $('#addNewsBtn')?.addEventListener('click',()=>openNews());$('#newsForm')?.addEventListener('submit',saveNews);$('#newsSearch')?.addEventListener('input',()=>{S.newsPage=1;renderNewsAdmin();});$('#newsYear')?.addEventListener('change',()=>{S.newsPage=1;renderNewsAdmin();});$('#newsStatus')?.addEventListener('change',()=>{S.newsPage=1;renderNewsAdmin();});
  $('#newsCoverFile')?.addEventListener('change',async e=>{const f=e.target.files?.[0],img=$('#newsCoverPreviewImage'),empty=$('#newsCoverPreviewEmpty');if(!f)return;try{img.src=await readFileDataUrl(f);img.classList.remove('hidden');empty.classList.add('hidden');}catch(err){toast(err.message,true);}});
  $('#addGalleryAlbumBtn')?.addEventListener('click',()=>openGalleryAlbum());$('#galleryAlbumForm')?.addEventListener('submit',saveGalleryAlbum);$('#galleryPhotoForm')?.addEventListener('submit',saveGalleryPhoto);$('#galleryAlbumSearch')?.addEventListener('input',renderGalleryAlbums);$('#galleryPhotoFiles')?.addEventListener('change',e=>uploadGalleryPhotos(e.target.files));$('#editGalleryAlbumBtn')?.addEventListener('click',()=>openGalleryAlbum(S.selectedGalleryAlbumId));$('#deleteGalleryAlbumBtn')?.addEventListener('click',deleteSelectedGalleryAlbum);bindGalleryDropZone();
  $('#galleryAdminFirstPage')?.addEventListener('click',()=>setGalleryAdminPage(1));$('#galleryAdminPrevPage')?.addEventListener('click',()=>setGalleryAdminPage(S.galleryPhotoPage-1));$('#galleryAdminNextPage')?.addEventListener('click',()=>setGalleryAdminPage(S.galleryPhotoPage+1));$('#galleryAdminLastPage')?.addEventListener('click',()=>setGalleryAdminPage(Math.ceil(S.galleryPhotos.length/S.galleryPhotoPageSize)||1));$('#galleryAdminPageInput')?.addEventListener('change',e=>setGalleryAdminPage(e.target.value));$('#galleryAdminPageInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();setGalleryAdminPage(e.target.value);}});
  $$('[data-admin-gallery-tab]').forEach(b=>b.addEventListener('click',()=>setAdminGalleryTab(b.dataset.adminGalleryTab)));$('#addGalleryVideoBtn')?.addEventListener('click',()=>openGalleryVideo());$('#galleryVideoForm')?.addEventListener('submit',saveGalleryVideo);$('#galleryVideoSearch')?.addEventListener('input',()=>{S.galleryVideoPage=1;renderGalleryVideosAdmin();});$('#galleryVideoUrl')?.addEventListener('input',updateGalleryVideoPreview);
  $('#galleryVideoAdminFirstPage')?.addEventListener('click',()=>setGalleryVideoPage(1));$('#galleryVideoAdminPrevPage')?.addEventListener('click',()=>setGalleryVideoPage(S.galleryVideoPage-1));$('#galleryVideoAdminNextPage')?.addEventListener('click',()=>setGalleryVideoPage(S.galleryVideoPage+1));$('#galleryVideoAdminLastPage')?.addEventListener('click',()=>setGalleryVideoPage(galleryVideoTotalPages()));$('#galleryVideoAdminPageInput')?.addEventListener('change',e=>setGalleryVideoPage(e.target.value));
  $('#addContactBtn')?.addEventListener('click',()=>openContact());$('#contactForm')?.addEventListener('submit',saveContact);
  $('#addUserBtn').addEventListener('click',()=>openUser());$('#userForm').addEventListener('submit',saveUser);$('#saveSettingsBtn').addEventListener('click',saveSettings);$('#settingsFloatingSaveBtn')?.addEventListener('click',saveSettings);$('#refreshAudit').addEventListener('click',loadAudit);
  $('#exportJson').addEventListener('click',()=>{switchView('settings');setTimeout(()=>$('#backupExportPassword')?.focus(),0);});$('#exportGedcom').addEventListener('click',()=>downloadProtected('/api/admin/export/gedcom'));
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.admin-modal.open').forEach(m=>m.classList.remove('open'));});
  document.addEventListener('click',e=>{if(!e.target.closest('.relation-picker'))$$('.relation-options').forEach(x=>x.hidden=true);});
  $('#peopleFirstPage')?.addEventListener('click',()=>setPeoplePage(1));$('#peoplePrevPage')?.addEventListener('click',()=>setPeoplePage(S.peoplePage-1));$('#peopleNextPage')?.addEventListener('click',()=>setPeoplePage(S.peoplePage+1));$('#peopleLastPage')?.addEventListener('click',()=>setPeoplePage(Math.ceil(filteredPeople().length/S.peoplePageSize)||1));$('#peoplePageInput')?.addEventListener('change',e=>setPeoplePage(e.target.value));$('#peoplePageInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();setPeoplePage(e.target.value);}});
  bindSimplePager('branches','branchesPage',()=>S.branches,renderBranches);bindSimplePager('news','newsPage',newsRows,renderNewsAdmin);bindSimplePager('contributions','contributionsPage',contributionRows,renderContributions);bindSimplePager('comments','commentsPage',()=>S.comments,renderComments);bindSimplePager('users','usersPage',()=>S.users,renderUsers);bindSimplePager('audit','auditPage',()=>S.audit,renderAudit);bindSimplePager('recent','recentPage',()=>S.recentAudit,renderRecentAudit);
}
async function bootstrap(){try{const a=await api('/api/auth/me',{csrf:false});S.auth=a;S.csrf=a.csrf_token||'';if(!a.authenticated){showLogin();return;}showApp();await refreshAll();if(a.user.must_change_password){toast('Hãy đổi mật khẩu quản trị được tạo lần đầu.');openModal('passwordModal');}}catch(e){showLogin();}}
function showLogin(){$('#loginScreen').classList.remove('hidden');}function showApp(){$('#loginScreen').classList.add('hidden');const u=S.auth.user;$('#sidebarUser').textContent=u.display_name;$('#sidebarRole').textContent=u.role.toUpperCase();const isAdmin=u.role==='admin';$$('.admin-only').forEach(x=>x.classList.toggle('hidden',!isAdmin));const canEdit=['admin','editor'].includes(u.role);$$('.editor-action').forEach(x=>x.classList.toggle('hidden',!canEdit));const canGallery=isAdmin||!!u.can_manage_gallery;$$('.gallery-nav,.gallery-action').forEach(x=>x.classList.toggle('hidden',!canGallery));if(!canGallery&&$('#view-gallery')?.classList.contains('active'))switchView('dashboard');}
async function login(e){e.preventDefault();const st=$('#loginStatus');st.textContent='';try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('#loginUsername').value,password:$('#loginPassword').value})});S.auth={authenticated:true,user:d.user,csrf_token:d.csrf_token};S.csrf=d.csrf_token;showApp();await refreshAll();}catch(err){st.textContent=err.message;}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'});}catch{}location.reload();}
async function changePassword(e){e.preventDefault();const st=$('#passwordStatus');st.textContent='';try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:$('#currentPassword').value,new_password:$('#newPassword').value})});toast('Đã đổi mật khẩu. Vui lòng đăng nhập lại.');setTimeout(()=>location.reload(),700);}catch(err){st.textContent=err.message;}}

async function refreshAll(){const canGallery=S.auth.user.role==='admin'||!!S.auth.user.can_manage_gallery;await Promise.all([loadDashboard(),loadPeople(),loadBranches(),loadContributions(),loadNews(),canGallery?loadGallery():Promise.resolve(),S.auth.user.role==='admin'?loadAdminData():Promise.resolve()]);}
async function loadDashboard(){const d=await api('/api/admin/dashboard');S.settings=d.settings||{};renderDashboard(d.stats||{});}
async function loadPeople(){const d=await api('/api/admin/people');S.people=d.people||[];renderPeople();}
async function loadBranches(){const d=await api('/api/admin/branches');S.branches=d.branches||[];renderBranches();}
async function loadContributions(){const d=await api('/api/admin/contributions');S.contributions=d.contributions||[];S.contributionYears=d.years||[];S.contributionSummary=d.summary||{};renderContributionYearOptions();renderContributions();}
async function loadNews(){const d=await api('/api/admin/news');S.news=d.news||[];S.newsYears=d.years||[];renderNewsYearOptions();renderNewsAdmin();}
async function loadGallery(){const d=await api('/api/admin/gallery');S.galleryAlbums=d.albums||[];S.galleryVideos=d.videos||[];renderGalleryAlbums();renderGalleryVideosAdmin();if(S.selectedGalleryAlbumId&&!S.galleryAlbums.some(a=>a.id===S.selectedGalleryAlbumId))S.selectedGalleryAlbumId=null;if(S.selectedGalleryAlbumId)await loadGalleryPhotos(S.selectedGalleryAlbumId);else renderGallerySelected();}
async function loadGalleryPhotos(albumId){if(!albumId)return;const changed=S.selectedGalleryAlbumId!==albumId;const d=await api(`/api/admin/gallery/albums/${encodeURIComponent(albumId)}/photos`);S.selectedGalleryAlbumId=albumId;S.galleryPhotos=d.photos||[];if(changed)S.galleryPhotoPage=1;renderGalleryAlbums();renderGallerySelected();}
async function loadAdminData(){await Promise.all([loadUsers(),loadComments(),loadAudit(),loadSettings(),loadContacts()]);}
async function loadUsers(){const d=await api('/api/admin/users');S.users=d.users||[];renderUsers();}async function loadContacts(){if(S.auth?.user?.role!=='admin')return;const d=await api('/api/admin/contacts');S.contacts=d.contacts||[];renderContactsAdmin();}async function loadComments(){const d=await api('/api/admin/comments');S.comments=d.comments||[];renderComments();}async function loadAudit(){const d=await api('/api/admin/audit');S.audit=d.audit||[];S.recentAudit=S.audit;renderAudit();renderRecentAudit();}async function loadSettings(){const d=await api('/api/admin/settings');S.settings=d.settings||{};renderSettings();}
function renderDashboard(stats){const items=[['Tổng cá thể',stats.total||0,'Trong toàn bộ cây'],['Thế hệ',stats.generations||0,'Số đời hiện có'],['Chi / nhánh',stats.branches||0,'Cây nhánh đã tạo'],['Phương danh',stats.contributions||0,'Lượt công đức đã ghi nhận'],['Tin tức',stats.news||0,'Bài viết đã tạo'],['Bình luận',stats.comments||0,'Đang hiển thị'],['User hoạt động',stats.users||0,'Có quyền đăng nhập']];$('#dashboardMetrics').innerHTML=items.map(([l,n,s])=>`<div class="metric-card"><span>${esc(l)}</span><strong>${n}</strong><small>${esc(s)}</small></div>`).join('');renderRecentAudit();}
function filteredPeople(){const q=$('#peopleSearch')?.value.trim().toLocaleLowerCase('vi')||'';const privacy=$('#peoplePrivacy')?.value||'';return S.people.filter(p=>(!q||`${p.full_name} ${p.family_code||''} ${p.birth_date||''} ${birthYear(p.birth_date)}`.toLocaleLowerCase('vi').includes(q))&&(!privacy||p.privacy_mode===privacy));}
function setPeoplePage(page){const rows=filteredPeople();const totalPages=Math.max(1,Math.ceil(rows.length/S.peoplePageSize));S.peoplePage=Math.min(totalPages,Math.max(1,Number(page)||1));renderPeople();}
function renderPeoplePagination(totalRows,totalPages){const start=totalRows?((S.peoplePage-1)*S.peoplePageSize)+1:0;const end=Math.min(S.peoplePage*S.peoplePageSize,totalRows);const info=$('#peoplePageInfo');if(info)info.textContent=totalRows?`Hiển thị ${start}–${end} / ${totalRows} cá thể · Trang ${S.peoplePage}/${totalPages}`:'Không có cá thể phù hợp';const input=$('#peoplePageInput');if(input){input.value=String(S.peoplePage);input.max=String(totalPages);}const first=$('#peopleFirstPage'),prev=$('#peoplePrevPage'),next=$('#peopleNextPage'),last=$('#peopleLastPage');if(first)first.disabled=S.peoplePage<=1;if(prev)prev.disabled=S.peoplePage<=1;if(next)next.disabled=S.peoplePage>=totalPages;if(last)last.disabled=S.peoplePage>=totalPages;}
function renderPeople(){const rows=filteredPeople();const totalPages=Math.max(1,Math.ceil(rows.length/S.peoplePageSize));if(S.peoplePage>totalPages)S.peoplePage=totalPages;if(S.peoplePage<1)S.peoplePage=1;const start=(S.peoplePage-1)*S.peoplePageSize;const pageRows=rows.slice(start,start+S.peoplePageSize);const by=new Map(S.people.map(p=>[p.id,p]));const canEdit=['admin','editor'].includes(S.auth.user.role);$('#peopleTable').innerHTML=pageRows.length?pageRows.map((p,i)=>{const img=p.image_url||`/assets/avatar-${p.gender==='other'?'placeholder':p.gender}.svg`;const parents=[p.father_id,p.mother_id].filter(Boolean).map(id=>by.get(id)?.full_name).filter(Boolean).join(' / ')||'—';const divorced=new Set(p.divorced_spouse_ids||[]);const ordered=orderedSpouseIdsForPerson(p);const spouseHtml=ordered.map((id,index)=>{const sp=by.get(id);if(!sp)return '';const orderLabel=ordered.length>1?spouseOrderLabel(p.gender,index,ordered.length):'';return `<span class="spouse-cell-item">${orderLabel?`<b>${esc(orderLabel)}:</b> `:''}${esc(sp.full_name)}${divorced.has(id)?'<small>Đã ly hôn</small>':''}</span>`;}).filter(Boolean).join('')||'—';return `<tr><td class="row-number">${start+i+1}</td><td><div class="table-person"><img src="${attr(img)}" alt=""><div><strong>${esc(p.full_name)}</strong><span>${esc(p.family_code||'Chưa có mã')} · ${p.is_deceased?'Đã mất':'Đang sống'}</span></div></div></td><td>${esc(birthYear(p.birth_date)||'—')}</td><td>Đời ${p.level}</td><td>${esc(parents)}</td><td><div class="spouse-cell">${spouseHtml}</div></td><td><span class="badge ${p.privacy_mode}">${privacyLabel(p.privacy_mode)}</span></td><td>${time(p.updated_at)}</td><td><div class="row-actions">${canEdit?`<button data-edit-person="${attr(p.id)}">Sửa</button><button data-delete-person="${attr(p.id)}">Xóa</button>`:'<span>Chỉ xem</span>'}</div></td></tr>`;}).join(''):'<tr><td colspan="9" class="empty-row">Không có cá thể phù hợp.</td></tr>';renderPeoplePagination(rows.length,totalPages);$$('[data-edit-person]').forEach(b=>b.onclick=()=>openPerson(b.dataset.editPerson));$$('[data-delete-person]').forEach(b=>b.onclick=()=>deletePerson(b.dataset.deletePerson));}
function bindSimplePager(prefix,pageKey,rowsFn,renderFn){const first=$(`#${prefix}FirstPage`),prev=$(`#${prefix}PrevPage`),next=$(`#${prefix}NextPage`),last=$(`#${prefix}LastPage`),input=$(`#${prefix}PageInput`);const set=page=>{const rows=rowsFn()||[];const totalPages=Math.max(1,Math.ceil(rows.length/S.adminPageSize));S[pageKey]=Math.min(totalPages,Math.max(1,Number(page)||1));renderFn();};first?.addEventListener('click',()=>set(1));prev?.addEventListener('click',()=>set(S[pageKey]-1));next?.addEventListener('click',()=>set(S[pageKey]+1));last?.addEventListener('click',()=>set(Math.ceil((rowsFn()||[]).length/S.adminPageSize)||1));input?.addEventListener('change',e=>set(e.target.value));input?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();set(e.target.value);}});}
function simplePage(rows,pageKey){const totalRows=rows.length;const totalPages=Math.max(1,Math.ceil(totalRows/S.adminPageSize));if(S[pageKey]>totalPages)S[pageKey]=totalPages;if(S[pageKey]<1)S[pageKey]=1;const start=(S[pageKey]-1)*S.adminPageSize;return {pageRows:rows.slice(start,start+S.adminPageSize),start,totalRows,totalPages};}
function renderSimplePagination(prefix,pageKey,totalRows,totalPages,label='bản ghi'){const page=S[pageKey];const start=totalRows?((page-1)*S.adminPageSize)+1:0;const end=Math.min(page*S.adminPageSize,totalRows);const info=$(`#${prefix}PageInfo`);if(info)info.textContent=totalRows?`Hiển thị ${start}–${end} / ${totalRows} ${label} · Trang ${page}/${totalPages}`:`Không có ${label}`;const input=$(`#${prefix}PageInput`);if(input){input.value=String(page);input.max=String(totalPages);}for(const [suffix,disabled] of [['FirstPage',page<=1],['PrevPage',page<=1],['NextPage',page>=totalPages],['LastPage',page>=totalPages]]){const btn=$(`#${prefix}${suffix}`);if(btn)btn.disabled=disabled;}}
function renderRecentAudit(){const host=$('#recentAudit');if(!host)return;const {pageRows,start,totalRows,totalPages}=simplePage(S.recentAudit,'recentPage');host.innerHTML=pageRows.length?pageRows.map((a,i)=>`<div class="activity-item numbered"><span class="activity-number">${start+i+1}</span><div><strong>${esc(a.display_name||a.username||'Hệ thống')}</strong> · ${esc(actionLabel(a.action))}<small>${time(a.created_at)}</small></div></div>`).join(''):'<div class="activity-item">Chưa có hoạt động.</div>';renderSimplePagination('recent','recentPage',totalRows,totalPages,'hoạt động');}

function renderBranches(){
  const host=$('#branchesTable');if(!host)return;const canEdit=['admin','editor'].includes(S.auth.user.role);const {pageRows,start,totalRows,totalPages}=simplePage(S.branches,'branchesPage');
  host.innerHTML=pageRows.length?pageRows.map((b,i)=>`<tr><td class="row-number">${start+i+1}</td><td><strong>${esc(b.name)}</strong>${b.description?`<br><span style="color:#999">${esc(b.description.slice(0,110))}</span>`:''}</td><td><strong>${esc(b.root_name)}</strong><div class="branch-root-meta"><span>Đời ${b.root_level}</span>${birthYear(b.root_birth_date)?`<span>Sinh ${esc(birthYear(b.root_birth_date))}</span>`:''}</div></td><td>${b.member_count} người</td><td>${b.is_public?'<span class="badge public">Công khai</span>':'<span class="badge private">Ẩn</span>'}</td><td><a class="ghost-btn" style="text-decoration:none;padding:6px 9px" href="/?chi=${encodeURIComponent(b.slug)}" target="_blank">Mở cây ↗</a></td><td><div class="row-actions">${canEdit?`<button data-edit-branch="${attr(b.id)}">Sửa</button><button data-delete-branch="${attr(b.id)}">Xóa</button>`:'<span>Chỉ xem</span>'}</div></td></tr>`).join(''):'<tr><td colspan="7" class="empty-row">Chưa có Chi. Hãy tạo Chi và chọn một cá thể làm gốc.</td></tr>';
  renderSimplePagination('branches','branchesPage',totalRows,totalPages,'Chi');$$('[data-edit-branch]').forEach(b=>b.onclick=()=>openBranch(b.dataset.editBranch));$$('[data-delete-branch]').forEach(b=>b.onclick=()=>deleteBranch(b.dataset.deleteBranch));
}


function contributionRows(){
  const q=($('#contributionSearch')?.value||'').trim().toLocaleLowerCase('vi'),year=$('#contributionYear')?.value||'',sort=$('#contributionSort')?.value||'date_desc';
  const rows=S.contributions.filter(r=>(!q||String(r.donor_name||'').toLocaleLowerCase('vi').includes(q))&&(!year||String(r.contribution_date||'').startsWith(`${year}-`)));
  const text=(a,b)=>String(a||'').localeCompare(String(b||''),'vi',{sensitivity:'base'});
  if(sort==='amount_desc')rows.sort((a,b)=>Number(b.amount||0)-Number(a.amount||0)||String(b.contribution_date||'').localeCompare(String(a.contribution_date||''))||text(a.donor_name,b.donor_name));
  else if(sort==='amount_asc')rows.sort((a,b)=>Number(a.amount||0)-Number(b.amount||0)||String(b.contribution_date||'').localeCompare(String(a.contribution_date||''))||text(a.donor_name,b.donor_name));
  else if(sort==='date_asc')rows.sort((a,b)=>String(a.contribution_date||'').localeCompare(String(b.contribution_date||''))||text(a.donor_name,b.donor_name));
  else if(sort==='year_desc')rows.sort((a,b)=>String(b.contribution_date||'').slice(0,4).localeCompare(String(a.contribution_date||'').slice(0,4))||String(b.contribution_date||'').localeCompare(String(a.contribution_date||''))||text(a.donor_name,b.donor_name));
  else if(sort==='year_asc')rows.sort((a,b)=>String(a.contribution_date||'').slice(0,4).localeCompare(String(b.contribution_date||'').slice(0,4))||String(b.contribution_date||'').localeCompare(String(a.contribution_date||''))||text(a.donor_name,b.donor_name));
  else if(sort==='name_asc')rows.sort((a,b)=>text(a.donor_name,b.donor_name)||String(b.contribution_date||'').localeCompare(String(a.contribution_date||'')));
  else rows.sort((a,b)=>String(b.contribution_date||'').localeCompare(String(a.contribution_date||''))||Number(b.amount||0)-Number(a.amount||0)||text(a.donor_name,b.donor_name));
  return rows;
}
function renderContributionYearOptions(){const el=$('#contributionYear');if(!el)return;const current=el.value;el.innerHTML='<option value="">Tất cả các năm</option>'+S.contributionYears.map(y=>`<option value="${attr(y)}">Năm ${esc(y)}</option>`).join('');if(S.contributionYears.includes(current))el.value=current;}
function renderContributions(){const host=$('#contributionsTable');if(!host)return;const rows=contributionRows(),{pageRows,start,totalRows,totalPages}=simplePage(rows,'contributionsPage'),canEdit=['admin','editor'].includes(S.auth.user.role);host.innerHTML=pageRows.length?pageRows.map((r,i)=>`<tr><td class="row-number">${start+i+1}</td><td><strong class="contribution-donor-name">${esc(r.donor_name)}</strong></td><td class="contribution-address-cell">${esc(r.address||'—')}</td><td class="contribution-copy-cell">${esc(r.contribution_content||'—')}</td><td><strong class="contribution-money">${money(r.amount)}</strong></td><td>${esc(contributionDate(r.contribution_date))}</td><td class="contribution-note-cell">${esc(r.notes||'—')}</td><td><div class="row-actions">${canEdit?`<button data-edit-contribution="${attr(r.id)}">Sửa</button><button data-delete-contribution="${attr(r.id)}">Xóa</button>`:'<span>Chỉ xem</span>'}</div></td></tr>`).join(''):'<tr><td colspan="8" class="empty-row">Chưa có phương danh công đức phù hợp.</td></tr>';renderSimplePagination('contributions','contributionsPage',totalRows,totalPages,'bản ghi');const sum=$('#contributionAdminSummary');if(sum){const total=rows.reduce((a,r)=>a+Number(r.amount||0),0),donors=new Set(rows.map(r=>String(r.donor_name||'').toLocaleLowerCase('vi'))).size;sum.innerHTML=`<div><span>Bản ghi</span><strong>${new Intl.NumberFormat('vi-VN').format(rows.length)}</strong></div><div><span>Phương danh</span><strong>${new Intl.NumberFormat('vi-VN').format(donors)}</strong></div><div><span>Tổng giá trị</span><strong>${money(total)}</strong></div>`;}$$('[data-edit-contribution]',host).forEach(b=>b.onclick=()=>openContribution(b.dataset.editContribution));$$('[data-delete-contribution]',host).forEach(b=>b.onclick=()=>deleteContribution(b.dataset.deleteContribution));}
function localDateInput(){const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`;}
function openContribution(id=null){S.editContributionId=id;const r=id?S.contributions.find(x=>x.id===id):null,form=$('#contributionForm');if(!form)return;form.reset();$('#contributionModalTitle').textContent=r?'Sửa phương danh công đức':'Thêm phương danh công đức';form.elements.donor_name.value=r?.donor_name||'';form.elements.address.value=r?.address||'';form.elements.contribution_content.value=r?.contribution_content||'';form.elements.amount.value=r?.amount??'';form.elements.contribution_date.value=r?.contribution_date||localDateInput();form.elements.notes.value=r?.notes||'';$('#contributionFormStatus').textContent='';openModal('contributionModal');}
async function saveContribution(e){e.preventDefault();const fd=new FormData(e.target),body={donor_name:String(fd.get('donor_name')||''),address:String(fd.get('address')||''),contribution_content:String(fd.get('contribution_content')||''),amount:Number(fd.get('amount')||0),contribution_date:String(fd.get('contribution_date')||''),notes:String(fd.get('notes')||'')},st=$('#contributionFormStatus');st.textContent='';try{await api(S.editContributionId?`/api/admin/contributions/${encodeURIComponent(S.editContributionId)}`:'/api/admin/contributions',{method:S.editContributionId?'PUT':'POST',body:JSON.stringify(body)});closeModal('contributionModal');toast(S.editContributionId?'Đã cập nhật phương danh công đức.':'Đã thêm phương danh công đức.');await loadContributions();}catch(err){st.textContent=err.message;}}
async function deleteContribution(id){const r=S.contributions.find(x=>x.id===id);if(!r||!confirm(`Xóa bản ghi công đức của “${r.donor_name}” trị giá ${money(r.amount)}?`))return;try{await api(`/api/admin/contributions/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Đã xóa bản ghi công đức.');await loadContributions();}catch(e){toast(e.message,true);}}


function galleryCanDelete(){return S.auth?.user?.role==='admin';}
function galleryFilteredAlbums(){const q=($('#galleryAlbumSearch')?.value||'').trim().toLocaleLowerCase('vi');return S.galleryAlbums.filter(a=>!q||`${a.title} ${a.description||''}`.toLocaleLowerCase('vi').includes(q));}
function renderGalleryAlbums(){const host=$('#galleryAlbumAdminList');if(!host)return;const rows=galleryFilteredAlbums();host.innerHTML=rows.length?rows.map(a=>`<button class="gallery-admin-album-card ${a.id===S.selectedGalleryAlbumId?'active':''}" data-gallery-album="${attr(a.id)}"><span class="gallery-admin-cover">${a.cover_url?`<img src="${attr(a.cover_url)}" alt="">`:'<span>▦</span>'}</span><span class="gallery-admin-album-copy"><strong>${esc(a.title)}</strong><small>${a.photo_count} ảnh · ${a.is_public?'Công khai':'Đang ẩn'}</small></span><span class="gallery-admin-chevron">›</span></button>`).join(''):'<div class="gallery-admin-empty">Chưa có thư mục ảnh phù hợp.</div>';$$('[data-gallery-album]',host).forEach(b=>b.onclick=()=>loadGalleryPhotos(b.dataset.galleryAlbum));}
function setGalleryAdminPage(page){const total=Math.max(1,Math.ceil(S.galleryPhotos.length/S.galleryPhotoPageSize));S.galleryPhotoPage=Math.min(total,Math.max(1,Number(page)||1));renderGallerySelected();}
function renderGalleryAdminPagination(totalRows,totalPages){const pager=$('#galleryAdminPagination');if(!pager)return;const start=totalRows?((S.galleryPhotoPage-1)*S.galleryPhotoPageSize)+1:0;const end=Math.min(S.galleryPhotoPage*S.galleryPhotoPageSize,totalRows);$('#galleryAdminPageInfo').textContent=totalRows?`Hiển thị ${start}–${end} / ${totalRows} ảnh · Trang ${S.galleryPhotoPage}/${totalPages}`:'Chưa có ảnh';const input=$('#galleryAdminPageInput');if(input){input.value=String(S.galleryPhotoPage);input.max=String(totalPages);}$('#galleryAdminPageTotal').textContent=`/ ${totalPages}`;$('#galleryAdminFirstPage').disabled=S.galleryPhotoPage<=1;$('#galleryAdminPrevPage').disabled=S.galleryPhotoPage<=1;$('#galleryAdminNextPage').disabled=S.galleryPhotoPage>=totalPages;$('#galleryAdminLastPage').disabled=S.galleryPhotoPage>=totalPages;}
function renderGallerySelected(){
  const album=S.galleryAlbums.find(a=>a.id===S.selectedGalleryAlbumId);const empty=$('#gallerySelectedEmpty'),content=$('#gallerySelectedContent');
  if(!album){empty?.classList.remove('hidden');content?.classList.add('hidden');return;}
  empty?.classList.add('hidden');content?.classList.remove('hidden');$('#gallerySelectedTitle').textContent=album.title;$('#gallerySelectedDescription').textContent=album.description||`${album.photo_count} ảnh · ${album.is_public?'Đang hiển thị công khai':'Đang ẩn khỏi trang công khai'}`;
  const host=$('#galleryAdminPhotoGrid');if(!host)return;
  const totalRows=S.galleryPhotos.length,totalPages=Math.max(1,Math.ceil(totalRows/S.galleryPhotoPageSize));if(S.galleryPhotoPage>totalPages)S.galleryPhotoPage=totalPages;if(S.galleryPhotoPage<1)S.galleryPhotoPage=1;const start=(S.galleryPhotoPage-1)*S.galleryPhotoPageSize;const pageRows=S.galleryPhotos.slice(start,start+S.galleryPhotoPageSize);
  host.innerHTML=pageRows.length?pageRows.map((p,i)=>`<article class="gallery-admin-photo-card"><button class="gallery-admin-photo-preview" data-edit-gallery-photo="${attr(p.id)}" title="Sửa ảnh"><img src="${attr(p.image_url)}" alt="${attr(p.title||`Ảnh ${start+i+1}`)}" loading="lazy"><span class="gallery-admin-photo-index">${start+i+1}</span></button><div class="gallery-admin-photo-meta"><strong>${esc(p.title||'Chưa đặt tiêu đề')}</strong><small>${esc(p.taken_date||p.caption||'Bấm Sửa để thêm chú thích')}</small><div class="row-actions"><button data-edit-gallery-photo="${attr(p.id)}">Sửa</button>${galleryCanDelete()?`<button class="danger-btn" data-delete-gallery-photo="${attr(p.id)}">Xóa</button>`:''}</div></div></article>`).join(''):'<div class="gallery-selected-empty compact"><div class="gallery-empty-icon">⌑</div><h3>Thư mục chưa có ảnh</h3><p>Dùng vùng tải ảnh phía trên để thêm nhiều ảnh cùng lúc.</p></div>';
  renderGalleryAdminPagination(totalRows,totalPages);
  $$('[data-edit-gallery-photo]',host).forEach(b=>b.onclick=()=>openGalleryPhoto(b.dataset.editGalleryPhoto));$$('[data-delete-gallery-photo]',host).forEach(b=>b.onclick=()=>deleteGalleryPhoto(b.dataset.deleteGalleryPhoto));
}
function openGalleryAlbum(id=null){S.editGalleryAlbumId=id;const album=id?S.galleryAlbums.find(a=>a.id===id):null;const form=$('#galleryAlbumForm');form.reset();$('#galleryAlbumModalTitle').textContent=album?'Sửa thư mục ảnh':'Tạo thư mục ảnh';form.elements.title.value=album?.title||'';form.elements.description.value=album?.description||'';form.elements.sort_order.value=album?.sort_order??0;form.elements.is_public.checked=album?!!album.is_public:true;const cover=$('#galleryCoverSelect');cover.innerHTML='<option value="">Tự động chọn ảnh đầu tiên</option>'+((id===S.selectedGalleryAlbumId?S.galleryPhotos:[]).map(p=>`<option value="${attr(p.id)}" ${album?.cover_photo_id===p.id?'selected':''}>${esc(p.title||p.taken_date||'Ảnh '+(S.galleryPhotos.indexOf(p)+1))}</option>`).join(''));$('#galleryCoverField')?.classList.toggle('hidden',!album);$('#galleryAlbumFormStatus').textContent='';openModal('galleryAlbumModal');}
async function saveGalleryAlbum(e){e.preventDefault();const st=$('#galleryAlbumFormStatus');st.textContent='';const fd=new FormData(e.target);const body={title:String(fd.get('title')||''),description:String(fd.get('description')||''),sort_order:Number(fd.get('sort_order')||0),is_public:fd.has('is_public')};if(S.editGalleryAlbumId)body.cover_photo_id=String(fd.get('cover_photo_id')||'');try{const d=await api(S.editGalleryAlbumId?`/api/admin/gallery/albums/${S.editGalleryAlbumId}`:'/api/admin/gallery/albums',{method:S.editGalleryAlbumId?'PUT':'POST',body:JSON.stringify(body)});closeModal('galleryAlbumModal');toast(S.editGalleryAlbumId?'Đã cập nhật thư mục ảnh.':'Đã tạo thư mục ảnh.');S.selectedGalleryAlbumId=d.album.id;await loadGallery();}catch(err){st.textContent=err.message;}}
function bindGalleryDropZone(){const zone=$('#galleryUploadZone');if(!zone)return;for(const ev of ['dragenter','dragover'])zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.add('dragging');});for(const ev of ['dragleave','drop'])zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.remove('dragging');});zone.addEventListener('drop',e=>uploadGalleryPhotos(e.dataTransfer?.files));}
async function uploadGalleryPhotos(files){const albumId=S.selectedGalleryAlbumId;const list=[...(files||[])].filter(f=>/^image\/(png|jpeg|webp)$/i.test(f.type));if(!albumId||!list.length)return;const progress=$('#galleryUploadProgress'),bar=$('#galleryProgressBar'),text=$('#galleryProgressText');progress?.classList.remove('hidden');let ok=0;try{for(let i=0;i<list.length;i++){const file=list[i];if(file.size>5*1024*1024){toast(`${file.name}: ảnh lớn hơn 5 MB.`,true);continue;}if(text)text.textContent=`Đang tải ${i+1}/${list.length}: ${file.name}`;if(bar)bar.style.width=`${Math.round((i/list.length)*100)}%`;try{const image_data=await readFileDataUrl(file);await api('/api/admin/gallery/photos',{method:'POST',body:JSON.stringify({album_id:albumId,title:file.name.replace(/\.[^.]+$/,''),image_data})});ok++;}catch(err){toast(`${file.name}: ${err.message}`,true);}}if(bar)bar.style.width='100%';if(ok)toast(`Đã thêm ${ok} ảnh vào thư mục.`);await Promise.all([loadGallery(),loadGalleryPhotos(albumId)]);}finally{if($('#galleryPhotoFiles'))$('#galleryPhotoFiles').value='';setTimeout(()=>progress?.classList.add('hidden'),500);}}
function openGalleryPhoto(id){const photo=S.galleryPhotos.find(p=>p.id===id);if(!photo)return;S.editGalleryPhotoId=id;const form=$('#galleryPhotoForm');form.reset();form.elements.title.value=photo.title||'';form.elements.caption.value=photo.caption||'';form.elements.taken_date.value=photo.taken_date||'';form.elements.sort_order.value=photo.sort_order??0;$('#galleryPhotoAlbumSelect').innerHTML=S.galleryAlbums.map(a=>`<option value="${attr(a.id)}" ${a.id===photo.album_id?'selected':''}>${esc(a.title)}</option>`).join('');$('#galleryPhotoEditPreview').src=photo.image_url;$('#galleryPhotoFormStatus').textContent='';openModal('galleryPhotoModal');}
async function saveGalleryPhoto(e){e.preventDefault();const photo=S.galleryPhotos.find(p=>p.id===S.editGalleryPhotoId);if(!photo)return;const st=$('#galleryPhotoFormStatus');st.textContent='';const fd=new FormData(e.target);const body={title:String(fd.get('title')||''),caption:String(fd.get('caption')||''),taken_date:String(fd.get('taken_date')||''),sort_order:Number(fd.get('sort_order')||0),album_id:String(fd.get('album_id')||photo.album_id)};try{const replacement=$('#galleryPhotoReplacement')?.files?.[0];if(replacement)body.image_data=await readFileDataUrl(replacement);const previousAlbum=photo.album_id;await api(`/api/admin/gallery/photos/${photo.id}`,{method:'PUT',body:JSON.stringify(body)});closeModal('galleryPhotoModal');toast('Đã cập nhật ảnh.');await loadGallery();S.selectedGalleryAlbumId=body.album_id;await loadGalleryPhotos(body.album_id);if(previousAlbum!==body.album_id)toast('Ảnh đã được chuyển sang thư mục mới.');}catch(err){st.textContent=err.message;}}
async function deleteGalleryPhoto(id){if(!galleryCanDelete()||!confirm('Xóa vĩnh viễn ảnh này khỏi thư viện? Thao tác không thể hoàn tác.'))return;try{await api(`/api/admin/gallery/photos/${id}`,{method:'DELETE'});toast('Đã xóa ảnh.');await Promise.all([loadGallery(),loadGalleryPhotos(S.selectedGalleryAlbumId)]);}catch(e){toast(e.message,true);}}
async function deleteSelectedGalleryAlbum(){const album=S.galleryAlbums.find(a=>a.id===S.selectedGalleryAlbumId);if(!album||!galleryCanDelete())return;if(!confirm(`Xóa vĩnh viễn thư mục “${album.title}” và toàn bộ ${album.photo_count} ảnh bên trong?\n\nChỉ admin mới thực hiện được thao tác này.`))return;try{await api(`/api/admin/gallery/albums/${album.id}`,{method:'DELETE'});toast('Đã xóa thư mục ảnh.');S.selectedGalleryAlbumId=null;S.galleryPhotos=[];await loadGallery();}catch(e){toast(e.message,true);}}


function renderNewsYearOptions(){const sel=$('#newsYear');if(!sel)return;const current=sel.value;sel.innerHTML='<option value="">Tất cả các năm</option>'+S.newsYears.map(y=>`<option value="${attr(y)}">Năm ${esc(y)}</option>`).join('');if(S.newsYears.includes(current))sel.value=current;}
function newsRows(){const q=$('#newsSearch')?.value.trim().toLocaleLowerCase('vi')||'',year=$('#newsYear')?.value||'',status=$('#newsStatus')?.value||'';return S.news.filter(r=>(!q||`${r.title||''} ${r.summary||''}`.toLocaleLowerCase('vi').includes(q))&&(!year||String(r.published_date||'').startsWith(`${year}-`))&&(!status||(status==='public'?r.is_public:!r.is_public)));}
function newsDate(v){const m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:(v||'—');}
function renderNewsAdmin(){const host=$('#newsTable');if(!host)return;const canEdit=['admin','editor'].includes(S.auth.user.role),rows=newsRows(),{pageRows,start,totalRows,totalPages}=simplePage(rows,'newsPage');host.innerHTML=pageRows.length?pageRows.map((r,i)=>`<tr><td class="row-number">${start+i+1}</td><td><div class="news-admin-row"><img src="${attr(r.cover_image_url||'/assets/logo.png')}" alt=""><div><strong>${esc(r.title)}</strong><span>${esc(r.summary||'Chưa có tóm tắt')}</span></div></div></td><td>${esc(newsDate(r.published_date))}</td><td>${r.is_public?'<span class="badge public">Công khai</span>':'<span class="badge private">Đang ẩn</span>'}</td><td>${time(r.updated_at)}</td><td><div class="row-actions"><a class="row-link-btn" href="/news.html?id=${encodeURIComponent(r.slug||r.id)}" target="_blank">Xem ↗</a>${canEdit?`<button data-edit-news="${attr(r.id)}">Sửa</button><button data-delete-news="${attr(r.id)}">Xóa</button>`:'<span>Chỉ xem</span>'}</div></td></tr>`).join(''):'<tr><td colspan="6" class="empty-row">Chưa có tin tức phù hợp.</td></tr>';renderSimplePagination('news','newsPage',totalRows,totalPages,'tin tức');$$('[data-edit-news]',host).forEach(b=>b.onclick=()=>openNews(b.dataset.editNews));$$('[data-delete-news]',host).forEach(b=>b.onclick=()=>deleteNews(b.dataset.deleteNews));}
let newsSavedRange=null;
function rememberNewsSelection(){const editor=$('#newsContentEditor'),sel=getSelection();if(editor&&sel?.rangeCount&&editor.contains(sel.anchorNode))newsSavedRange=sel.getRangeAt(0).cloneRange();}
function restoreNewsSelection(){const editor=$('#newsContentEditor');if(!editor)return;editor.focus();if(newsSavedRange&&editor.contains(newsSavedRange.commonAncestorContainer)){const sel=getSelection();sel.removeAllRanges();sel.addRange(newsSavedRange);}}
function initNewsEditor(){const editor=$('#newsContentEditor'),toolbar=$('#newsEditorToolbar');if(!editor||!toolbar||editor.dataset.ready==='1')return;editor.dataset.ready='1';$('#newsFontSelect').innerHTML=FONT_OPTIONS.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('');['keyup','mouseup','focus','input'].forEach(ev=>editor.addEventListener(ev,rememberNewsSelection));editor.addEventListener('paste',e=>{e.preventDefault();const text=e.clipboardData?.getData('text/plain')||'';document.execCommand('insertText',false,text);rememberNewsSelection();});toolbar.addEventListener('mousedown',e=>{if(e.target.closest('button,select,input'))rememberNewsSelection();});toolbar.addEventListener('click',e=>{const btn=e.target.closest('[data-news-cmd]');if(!btn)return;e.preventDefault();restoreNewsSelection();document.execCommand(btn.dataset.newsCmd,false,null);rememberNewsSelection();});$('#newsBlockFormat')?.addEventListener('change',e=>{restoreNewsSelection();document.execCommand('formatBlock',false,e.target.value);rememberNewsSelection();});$('#newsFontSelect')?.addEventListener('change',e=>{restoreNewsSelection();document.execCommand('fontName',false,richFontStack(e.target.value).split(',')[0].replaceAll('"',''));rememberNewsSelection();});$('#newsFontSize')?.addEventListener('change',e=>{restoreNewsSelection();document.execCommand('fontSize',false,'7');editor.querySelectorAll('font[size="7"]').forEach(el=>{el.removeAttribute('size');el.style.fontSize=`${Math.max(10,Math.min(56,Number(e.target.value)||16))}px`;});rememberNewsSelection();});$('#newsTextColor')?.addEventListener('input',e=>{restoreNewsSelection();document.execCommand('foreColor',false,e.target.value);rememberNewsSelection();});$('#newsLinkBtn')?.addEventListener('click',()=>{const href=prompt('Nhập liên kết (https://..., mailto:..., tel:... hoặc /đường-dẫn):','https://');if(!href)return;restoreNewsSelection();document.execCommand('createLink',false,href.trim());rememberNewsSelection();});$('#newsHrBtn')?.addEventListener('click',()=>{restoreNewsSelection();document.execCommand('insertHorizontalRule',false,null);rememberNewsSelection();});$('#newsClearFormatBtn')?.addEventListener('click',()=>{restoreNewsSelection();document.execCommand('removeFormat',false,null);document.execCommand('unlink',false,null);rememberNewsSelection();});$('#newsImageBtn')?.addEventListener('click',()=>$('#newsInlineImageFile')?.click());$('#newsInlineImageFile')?.addEventListener('change',uploadNewsInlineImage);}
async function uploadNewsInlineImage(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;try{const image_data=await readFileDataUrl(file),d=await api('/api/admin/news/images',{method:'POST',body:JSON.stringify({image_data})});restoreNewsSelection();const editor=$('#newsContentEditor'),figure=document.createElement('figure');figure.className='news-article-figure';const img=document.createElement('img');img.src=d.image_url;img.alt=file.name.replace(/\.[^.]+$/,'');img.loading='lazy';const cap=document.createElement('figcaption');cap.className='news-article-caption';cap.textContent='';figure.append(img,cap);const sel=getSelection();if(sel?.rangeCount&&editor.contains(sel.anchorNode)){const range=sel.getRangeAt(0);range.deleteContents();range.insertNode(figure);range.setStartAfter(figure);range.collapse(true);sel.removeAllRanges();sel.addRange(range);}else editor.appendChild(figure);const p=document.createElement('p');p.appendChild(document.createElement('br'));figure.after(p);newsSavedRange=null;toast('Đã chèn ảnh vào bài viết.');}catch(err){toast(err.message||'Không thể chèn ảnh.',true);}}
async function openNews(id=null){S.editNewsId=id;initNewsEditor();const form=$('#newsForm');if(!form)return;form.reset();let r=null;if(id){try{r=(await api(`/api/admin/news/${encodeURIComponent(id)}`)).article;}catch(err){toast(err.message,true);return;}}$('#newsModalTitle').textContent=r?'Sửa tin tức':'Thêm tin tức';$('#newsTitleInput').value=r?.title||'';$('#newsSummaryInput').value=r?.summary||'';$('#newsPublishedDate').value=r?.published_date||localDateInput();$('#newsSortOrder').value=r?.sort_order??0;$('#newsIsPublic').checked=r?!!r.is_public:true;$('#newsContentEditor').innerHTML=r?.content_html||'<p><br></p>';$('#newsRemoveCover').checked=false;$('#newsCoverFile').value='';const img=$('#newsCoverPreviewImage'),empty=$('#newsCoverPreviewEmpty');if(r?.cover_image_path&&r?.cover_image_url){img.src=r.cover_image_url;img.classList.remove('hidden');empty.classList.add('hidden');}else{img.removeAttribute('src');img.classList.add('hidden');empty.classList.remove('hidden');}$('#newsFormStatus').textContent='';newsSavedRange=null;openModal('newsModal');}
function newsEditorHtml(){const editor=$('#newsContentEditor'),clone=editor.cloneNode(true);clone.querySelectorAll('font').forEach(el=>{const span=document.createElement('span'),styles=[];const face=el.getAttribute('face');if(face)styles.push(`font-family:${face}`);const color=el.getAttribute('color');if(color)styles.push(`color:${color}`);const size=el.getAttribute('size');if(size&&/^\d+$/.test(size)){const px={1:10,2:12,3:16,4:18,5:24,6:32,7:36}[Number(size)]||16;styles.push(`font-size:${px}px`);}const existing=el.getAttribute('style');if(existing)styles.push(existing);if(styles.length)span.setAttribute('style',styles.join(';'));while(el.firstChild)span.appendChild(el.firstChild);el.replaceWith(span);});clone.querySelectorAll('[contenteditable],[data-placeholder]').forEach(el=>{el.removeAttribute('contenteditable');el.removeAttribute('data-placeholder');});return clone.innerHTML;}
async function saveNews(e){e.preventDefault();const st=$('#newsFormStatus');st.textContent='';const editor=$('#newsContentEditor');const body={title:$('#newsTitleInput').value.trim(),summary:$('#newsSummaryInput').value.trim(),content_html:newsEditorHtml(),published_date:$('#newsPublishedDate').value,sort_order:Number($('#newsSortOrder').value||0),is_public:$('#newsIsPublic').checked,remove_cover:$('#newsRemoveCover').checked};if(!body.title){st.textContent='Vui lòng nhập tiêu đề tin tức.';return;}if(!editor.textContent.trim()&&!editor.querySelector('img')){st.textContent='Vui lòng nhập nội dung tin tức.';return;}try{const cover=$('#newsCoverFile').files?.[0];if(cover)body.cover_image_data=await readFileDataUrl(cover);await api(S.editNewsId?`/api/admin/news/${encodeURIComponent(S.editNewsId)}`:'/api/admin/news',{method:S.editNewsId?'PUT':'POST',body:JSON.stringify(body)});closeModal('newsModal');toast(S.editNewsId?'Đã cập nhật tin tức.':'Đã đăng tin tức.');await Promise.all([loadNews(),loadDashboard()]);}catch(err){st.textContent=err.message;}}
async function deleteNews(id){const r=S.news.find(x=>x.id===id);if(!r||!confirm(`Xóa tin “${r.title}”?`))return;try{await api(`/api/admin/news/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Đã xóa tin tức.');await Promise.all([loadNews(),loadDashboard()]);}catch(e){toast(e.message,true);}}

function renderComments(){const {pageRows,start,totalRows,totalPages}=simplePage(S.comments,'commentsPage');$('#commentsTable').innerHTML=pageRows.length?pageRows.map((c,i)=>`<tr><td class="row-number">${start+i+1}</td><td><strong>${esc(c.display_name)}</strong></td><td style="max-width:500px;white-space:normal">${esc(c.message)}</td><td>${time(c.created_at)}</td><td>${c.deleted_at?'<span class="badge private">Đã xóa</span>':'<span class="badge public">Đang hiện</span>'}</td><td>${c.deleted_at?'—':`<button class="danger-btn" data-del-comment="${attr(c.id)}">Xóa</button>`}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-row">Chưa có bình luận.</td></tr>';renderSimplePagination('comments','commentsPage',totalRows,totalPages,'bình luận');$$('[data-del-comment]').forEach(b=>b.onclick=()=>deleteComment(b.dataset.delComment));}
function renderUsers(){const {pageRows,start,totalRows,totalPages}=simplePage(S.users,'usersPage');$('#usersTable').innerHTML=pageRows.length?pageRows.map((u,i)=>`<tr><td class="row-number">${start+i+1}</td><td><strong>${esc(u.display_name)}</strong><br><span style="color:#999">@${esc(u.username)}</span></td><td><span class="badge ${u.role}">${u.role}</span></td><td>${u.role==='admin'||u.can_manage_gallery?'<span class="badge public">Được quản lý</span>':'<span class="badge">Không</span>'}</td><td>${u.is_active?'<span class="badge public">Hoạt động</span>':'<span class="badge private">Đã khóa</span>'}</td><td>${u.last_login_at?time(u.last_login_at):'Chưa đăng nhập'}</td><td><div class="row-actions"><button data-edit-user="${attr(u.id)}">Sửa quyền</button></div></td></tr>`).join(''):'<tr><td colspan="7" class="empty-row">Chưa có người dùng.</td></tr>';renderSimplePagination('users','usersPage',totalRows,totalPages,'người dùng');$$('[data-edit-user]').forEach(b=>b.onclick=()=>openUser(b.dataset.editUser));}
function settingsFontOptions(selected='system'){const current=RICH_TEXT_FONTS.includes(String(selected||''))?String(selected):'system';return FONT_OPTIONS.map(([v,l])=>`<option value="${v}" ${current===v?'selected':''}>${l}</option>`).join('');}
const FUND_SUPPORT_SIZES=[12,14,16,18,20,24,28,32,36];
const RICH_TEXT_SIZES=[10,12,14,16,18,20,24,28,32,36,42,48,56,64];
