function richPlainText(tokens){return(tokens||[]).filter(x=>x?.type!=='image').map(x=>x.text||'').join('').replace(/\n+$/,'').trim();}
function richToolbar(editorId,{legacyFund=false,allowImage=false}={}){const p=legacyFund?'fundSupport':editorId;const boldId=legacyFund?'fundSupportBold':`${p}Bold`;const sizeId=legacyFund?'fundSupportSize':`${p}Size`;const clearId=legacyFund?'fundSupportClear':`${p}Clear`;return `<div class="fund-rich-toolbar rich-text-toolbar" data-rich-toolbar="${attr(editorId)}" role="toolbar" aria-label="Công cụ định dạng văn bản"><button type="button" id="${boldId}" data-rich-cmd="bold" title="In đậm"><b>B</b></button><button type="button" data-rich-cmd="italic" title="In nghiêng"><i>I</i></button><button type="button" data-rich-cmd="underline" title="Gạch chân"><u>U</u></button><button type="button" data-rich-cmd="strikeThrough" title="Gạch ngang"><s>S</s></button><select data-rich-font aria-label="Font chữ">${RICH_TEXT_FONTS.map(v=>`<option value="${v}">${FONT_LABELS[v]||v}</option>`).join('')}</select><select id="${sizeId}" data-rich-size aria-label="Cỡ chữ">${RICH_TEXT_SIZES.map(n=>`<option value="${n}" ${n===16?'selected':''}>${n}px</option>`).join('')}</select><label class="rich-color" title="Màu chữ"><span>A</span><input type="color" data-rich-color value="#4a4b47" aria-label="Màu chữ"></label><span class="rich-toolbar-sep"></span><button type="button" data-rich-cmd="justifyLeft" title="Căn trái">≡</button><button type="button" data-rich-cmd="justifyCenter" title="Căn giữa">☰</button><button type="button" data-rich-cmd="justifyRight" title="Căn phải">≣</button><button type="button" data-rich-cmd="justifyFull" title="Căn đều">▤</button>${allowImage?`<button type="button" data-rich-image-insert title="Chèn ảnh">▧ Ảnh</button><input type="file" data-rich-image-file accept="image/png,image/jpeg,image/webp" hidden>`:''}<button type="button" id="${clearId}" data-rich-clear title="Xóa định dạng">Xóa định dạng</button></div>`;}
function richEditorField(id,label,value,{fallback='',placeholder='Nhập nội dung…',note='',legacyFund=false,defaultAlign='left',allowImage=false}={}){return `<div class="form-field full rich-setting-field"><label>${esc(label)}</label>${richToolbar(id,{legacyFund,allowImage})}<div id="${attr(id)}" class="fund-rich-editor rich-text-editor" contenteditable="true" role="textbox" aria-multiline="true" data-placeholder="${attr(placeholder)}" data-default-align="${attr(defaultAlign)}"></div>${note?`<small>${note}</small>`:''}</div>`;}
function setupRichEditor(editorId){const editor=$('#'+editorId),toolbar=$(`[data-rich-toolbar="${editorId}"]`);if(!editor||!toolbar)return;let savedRange=null;const remember=()=>{const sel=getSelection();if(sel?.rangeCount&&editor.contains(sel.anchorNode))savedRange=sel.getRangeAt(0).cloneRange();};const restore=()=>{if(!savedRange)return;const sel=getSelection();sel.removeAllRanges();sel.addRange(savedRange);};['keyup','mouseup','focus','input'].forEach(ev=>editor.addEventListener(ev,remember));editor.addEventListener('paste',e=>{e.preventDefault();const text=e.clipboardData?.getData('text/plain')||'';document.execCommand('insertText',false,text);remember();});toolbar.addEventListener('mousedown',e=>{if(e.target.closest('button,select,input'))remember();});toolbar.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;e.preventDefault();if(btn.hasAttribute('data-rich-image-insert')){toolbar.querySelector('[data-rich-image-file]')?.click();return;}restore();editor.focus();if(btn.dataset.richCmd)document.execCommand(btn.dataset.richCmd,false,null);else if(btn.hasAttribute('data-rich-clear')){document.execCommand('removeFormat',false,null);document.execCommand('justifyLeft',false,null);}remember();});toolbar.querySelector('[data-rich-size]')?.addEventListener('change',e=>{restore();editor.focus();document.execCommand('fontSize',false,'7');editor.querySelectorAll('font[size="7"]').forEach(el=>{el.removeAttribute('size');el.style.fontSize=`${nearestRichSize(e.target.value)}px`;});remember();});toolbar.querySelector('[data-rich-font]')?.addEventListener('change',e=>{restore();editor.focus();document.execCommand('fontName',false,richFontStack(e.target.value).split(',')[0].replaceAll('"',''));remember();});toolbar.querySelector('[data-rich-color]')?.addEventListener('input',e=>{restore();editor.focus();document.execCommand('foreColor',false,e.target.value);remember();});const imageFile=toolbar.querySelector('[data-rich-image-file]');imageFile?.addEventListener('change',async()=>{const file=imageFile.files?.[0];imageFile.value='';if(!file)return;try{const data=await readFileDataUrl(file);const block=createRichImageBlock({type:'image',image_data:data,width:100,align:'center',alt:file.name});const range=savedRange;if(range&&editor.contains(range.commonAncestorContainer)){let top=range.startContainer.nodeType===Node.ELEMENT_NODE?range.startContainer:range.startContainer.parentElement;while(top&&top.parentElement!==editor)top=top.parentElement;if(top?.nextSibling)editor.insertBefore(block,top.nextSibling);else editor.appendChild(block);}else editor.appendChild(block);const line=document.createElement('div');line.className='rich-editor-line';line.appendChild(document.createElement('br'));editor.appendChild(line);toast('Đã chèn ảnh vào nội dung. Ảnh sẽ được tải lên khi Lưu cài đặt.');}catch(err){toast(err.message||'Không thể chèn ảnh.',true);}});}
// Backward-compatible names kept for v1.0.17 regression and older saved fund-support content.
function parseFundSupportTokens(value){return parseRichTokens(value,'',16,'left');}
