function setAdminGalleryTab(tab){const videos=tab==='videos';$$('[data-admin-gallery-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminGalleryTab===(videos?'videos':'photos')));$('#galleryAdminPhotosView')?.classList.toggle('hidden',videos);$('#galleryAdminVideosView')?.classList.toggle('hidden',!videos);if(videos)renderGalleryVideosAdmin();}
function galleryVideoRows(){const q=($('#galleryVideoSearch')?.value||'').trim().toLocaleLowerCase('vi');return S.galleryVideos.filter(v=>!q||String(v.title||'').toLocaleLowerCase('vi').includes(q));}
function galleryVideoTotalPages(){return Math.max(1,Math.ceil(galleryVideoRows().length/S.galleryVideoPageSize));}
function setGalleryVideoPage(page){S.galleryVideoPage=Math.min(galleryVideoTotalPages(),Math.max(1,Number(page)||1));renderGalleryVideosAdmin();}
function renderGalleryVideosAdmin(){const host=$('#galleryAdminVideoGrid');if(!host)return;const rows=galleryVideoRows(),tp=Math.max(1,Math.ceil(rows.length/S.galleryVideoPageSize));if(S.galleryVideoPage>tp)S.galleryVideoPage=tp;const start=(S.galleryVideoPage-1)*S.galleryVideoPageSize,pageRows=rows.slice(start,start+S.galleryVideoPageSize);host.innerHTML=pageRows.length?pageRows.map((v,i)=>`<article class="gallery-admin-video-card"><div class="gallery-admin-video-preview"><img src="${attr(v.thumbnail_url)}" alt=""><span>▶</span></div><div><strong>${esc(v.title)}</strong><small>${v.is_public?'Công khai':'Đang ẩn'} · #${start+i+1}</small><div class="row-actions"><button data-edit-gallery-video="${attr(v.id)}">Sửa</button><button class="danger-btn" data-delete-gallery-video="${attr(v.id)}">Xóa</button></div></div></article>`).join(''):'<div class="gallery-admin-empty">Chưa có video YouTube.</div>';$$('[data-edit-gallery-video]',host).forEach(b=>b.onclick=()=>openGalleryVideo(b.dataset.editGalleryVideo));$$('[data-delete-gallery-video]',host).forEach(b=>b.onclick=()=>deleteGalleryVideo(b.dataset.deleteGalleryVideo));const end=Math.min(start+pageRows.length,rows.length);$('#galleryVideoAdminPageInfo').textContent=rows.length?`Hiển thị ${start+1}–${end} / ${rows.length} video · Trang ${S.galleryVideoPage}/${tp}`:'Chưa có video';const input=$('#galleryVideoAdminPageInput');if(input){input.value=S.galleryVideoPage;input.max=tp;}$('#galleryVideoAdminPageTotal').textContent=`/ ${tp}`;$('#galleryVideoAdminFirstPage').disabled=S.galleryVideoPage<=1;$('#galleryVideoAdminPrevPage').disabled=S.galleryVideoPage<=1;$('#galleryVideoAdminNextPage').disabled=S.galleryVideoPage>=tp;$('#galleryVideoAdminLastPage').disabled=S.galleryVideoPage>=tp;}
function extractYoutubeIdClient(value){const raw=String(value||'').trim();if(/^[A-Za-z0-9_-]{11}$/.test(raw))return raw;try{const u=new URL(raw),h=u.hostname.toLowerCase().replace(/^www\./,'');let id='';if(h==='youtu.be')id=u.pathname.split('/').filter(Boolean)[0]||'';else if(['youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'].includes(h)){id=u.searchParams.get('v')||'';if(!id){const parts=u.pathname.split('/').filter(Boolean),i=parts.findIndex(x=>['embed','shorts','live'].includes(x));if(i>=0)id=parts[i+1]||'';}}return /^[A-Za-z0-9_-]{11}$/.test(id)?id:'';}catch{return '';}}
function updateGalleryVideoPreview(){const id=extractYoutubeIdClient($('#galleryVideoUrl')?.value),frame=$('#galleryVideoPreview'),empty=$('#galleryVideoPreviewEmpty');if(id){frame.src=`https://www.youtube-nocookie.com/embed/${id}?rel=0`;frame.classList.remove('hidden');empty.classList.add('hidden');}else{frame.src='about:blank';frame.classList.add('hidden');empty.classList.remove('hidden');}}
function openGalleryVideo(id=null){S.editGalleryVideoId=id;const v=id?S.galleryVideos.find(x=>x.id===id):null,form=$('#galleryVideoForm');form.reset();$('#galleryVideoModalAdminTitle').textContent=v?'Sửa video YouTube':'Thêm video YouTube';form.elements.title.value=v?.title||'';form.elements.youtube_url.value=v?.youtube_url||'';form.elements.sort_order.value=v?.sort_order??0;form.elements.is_public.checked=v?!!v.is_public:true;$('#galleryVideoFormStatus').textContent='';openModal('galleryVideoModalAdmin');updateGalleryVideoPreview();}
async function saveGalleryVideo(e){e.preventDefault();const fd=new FormData(e.target),body={title:String(fd.get('title')||''),youtube_url:String(fd.get('youtube_url')||''),sort_order:Number(fd.get('sort_order')||0),is_public:fd.has('is_public')},st=$('#galleryVideoFormStatus');st.textContent='';try{await api(S.editGalleryVideoId?`/api/admin/gallery/videos/${S.editGalleryVideoId}`:'/api/admin/gallery/videos',{method:S.editGalleryVideoId?'PUT':'POST',body:JSON.stringify(body)});closeModal('galleryVideoModalAdmin');toast(S.editGalleryVideoId?'Đã cập nhật video.':'Đã thêm video.');await loadGallery();setAdminGalleryTab('videos');}catch(err){st.textContent=err.message;}}
async function deleteGalleryVideo(id){const v=S.galleryVideos.find(x=>x.id===id);if(!v||!confirm(`Xóa video “${v.title}” khỏi Thư viện?`))return;try{await api(`/api/admin/gallery/videos/${id}`,{method:'DELETE'});toast('Đã xóa video.');await loadGallery();setAdminGalleryTab('videos');}catch(e){toast(e.message,true);}}

function renderContactsAdmin(){const host=$('#contactAdminGrid');if(!host)return;host.innerHTML=S.contacts.length?S.contacts.map((c,i)=>`<article class="contact-admin-card"><div class="contact-admin-card-photo">${c.image_url?`<img src="${attr(c.image_url)}" alt="">`:'<span>♙</span>'}</div><div><strong>${esc(c.name_text)}</strong><small>${esc(c.phone||'Chưa có số điện thoại')} · ${c.is_public?'Công khai':'Đang ẩn'}</small><div class="row-actions"><button data-edit-contact="${attr(c.id)}">Sửa</button><button class="danger-btn" data-delete-contact="${attr(c.id)}">Xóa</button></div></div></article>`).join(''):'<div class="gallery-admin-empty">Chưa có người liên hệ.</div>';$$('[data-edit-contact]',host).forEach(b=>b.onclick=()=>openContact(b.dataset.editContact));$$('[data-delete-contact]',host).forEach(b=>b.onclick=()=>deleteContact(b.dataset.deleteContact));}
function openContact(id=null){S.editContactId=id;const c=id?S.contacts.find(x=>x.id===id):null;$('#contactModalTitle').textContent=c?'Sửa người liên hệ':'Thêm người liên hệ';$('#contactNameEditorHost').innerHTML=richEditorField('contactNameEditor','Họ và tên *',c?.name_content,{fallback:c?.name_text||'',placeholder:'Nhập họ và tên…',defaultAlign:'left'});$('#contactPhoneEditorHost').innerHTML=richEditorField('contactPhoneEditor','Số điện thoại',c?.phone_content,{fallback:c?.phone||'',placeholder:'Ví dụ: 0989 871 186',note:'Có thể định dạng chữ; hệ thống vẫn lấy phần số để tạo nút gọi điện.',defaultAlign:'left'});$('#contactAddressEditorHost').innerHTML=richEditorField('contactAddressEditor','Địa chỉ',c?.address_content,{placeholder:'Nhập địa chỉ nhiều dòng…',defaultAlign:'left'});populateRichEditor($('#contactNameEditor'),c?.name_content,c?.name_text||'',22,'left');populateRichEditor($('#contactPhoneEditor'),c?.phone_content,c?.phone||'',15,'left');populateRichEditor($('#contactAddressEditor'),c?.address_content,'',15,'left');setupRichEditor('contactNameEditor');setupRichEditor('contactPhoneEditor');setupRichEditor('contactAddressEditor');$('#contactSortOrder').value=c?.sort_order??0;$('#contactIsPublic').checked=c?!!c.is_public:true;const preview=$('#contactImagePreview'),empty=$('#contactImageEmpty');if(c?.image_url){preview.src=c.image_url;preview.classList.remove('hidden');empty.classList.add('hidden');}else{preview.removeAttribute('src');preview.classList.add('hidden');empty.classList.remove('hidden');}$('#contactImageFile').value='';$('#contactRemoveImage').checked=false;$('#contactFormStatus').textContent='';$('#contactImageFile').onchange=()=>{const f=$('#contactImageFile').files?.[0];if(!f)return;const u=URL.createObjectURL(f);preview.src=u;preview.classList.remove('hidden');empty.classList.add('hidden');preview.onload=()=>URL.revokeObjectURL(u);$('#contactRemoveImage').checked=false;};openModal('contactModal');}
async function saveContact(e){e.preventDefault();const nameTokens=richEditorTokens($('#contactNameEditor'),1000),phoneTokens=richEditorTokens($('#contactPhoneEditor'),1000),addressTokens=richEditorTokens($('#contactAddressEditor'),4000),nameText=richPlainText(nameTokens).trim(),phoneText=richPlainText(phoneTokens).trim(),body={name_text:nameText,name_content:JSON.stringify(nameTokens),phone:phoneText,phone_content:JSON.stringify(phoneTokens),address_content:JSON.stringify(addressTokens),sort_order:Number($('#contactSortOrder').value||0),is_public:$('#contactIsPublic').checked,remove_image:$('#contactRemoveImage').checked},st=$('#contactFormStatus');if(!nameText){st.textContent='Họ và tên không được để trống.';return;}try{const f=$('#contactImageFile').files?.[0];if(f)body.image_data=await readFileDataUrl(f);await api(S.editContactId?`/api/admin/contacts/${S.editContactId}`:'/api/admin/contacts',{method:S.editContactId?'PUT':'POST',body:JSON.stringify(body)});closeModal('contactModal');toast(S.editContactId?'Đã cập nhật người liên hệ.':'Đã thêm người liên hệ.');await loadContacts();}catch(err){st.textContent=err.message;}}
async function deleteContact(id){const c=S.contacts.find(x=>x.id===id);if(!c||!confirm(`Xóa người liên hệ “${c.name_text}”?`))return;try{await api(`/api/admin/contacts/${id}`,{method:'DELETE'});toast('Đã xóa người liên hệ.');await loadContacts();}catch(e){toast(e.message,true);}}

function settingsTabButton(id,label,icon=''){const active=(S.settingsTab||'tree')===id;return `<button type="button" class="settings-tab-btn${active?' active':''}" data-settings-tab="${attr(id)}" role="tab" aria-selected="${active?'true':'false'}">${icon?`<span aria-hidden="true">${icon}</span>`:''}<b>${esc(label)}</b></button>`;}
function settingsPanel(id,html){const active=(S.settingsTab||'tree')===id;return `<section class="settings-tab-panel${active?' active':''}" data-settings-panel="${attr(id)}" role="tabpanel" ${active?'':'hidden'}>${html}</section>`;}
