  const file=$('#set_site_logo_file'),preview=$('#settingsLogoPreview'),remove=$('#set_remove_logo');file?.addEventListener('change',()=>{const f=file.files?.[0];if(!f)return;const url=URL.createObjectURL(f);preview.src=url;preview.onload=()=>URL.revokeObjectURL(url);if(remove)remove.checked=false;});remove?.addEventListener('change',()=>{if(remove.checked){if(file)file.value='';preview.src='/assets/logo.png';}});
  const qrFile=$('#set_fund_qr_file'),qrPreview=$('#settingsFundQrPreview'),qrEmpty=$('#settingsFundQrEmpty'),removeQr=$('#set_remove_fund_qr');qrFile?.addEventListener('change',()=>{const f=qrFile.files?.[0];if(!f)return;const url=URL.createObjectURL(f);qrPreview.src=url;qrPreview.classList.remove('hidden');qrEmpty?.classList.add('hidden');qrPreview.onload=()=>URL.revokeObjectURL(url);if(removeQr)removeQr.checked=false;});removeQr?.addEventListener('change',()=>{if(removeQr.checked){if(qrFile)qrFile.value='';qrPreview?.classList.add('hidden');qrEmpty?.classList.remove('hidden');}else if(qrSrc){qrPreview.src=qrSrc;qrPreview?.classList.remove('hidden');qrEmpty?.classList.add('hidden');}});
  const templeFiles=$('#set_contact_temple_files'),templeNew=$('#settingsTempleNewPreview');templeFiles?.addEventListener('change',()=>{for(const img of $$('img',templeNew))if(img.dataset.objectUrl)URL.revokeObjectURL(img.dataset.objectUrl);templeNew.replaceChildren();const files=[...(templeFiles.files||[])],removed=$$('[data-remove-temple-path]:checked').length,remain=Math.max(0,templePaths.length-removed);if(remain+files.length>10){toast(`Chỉ được tối đa 10 ảnh nhà thờ Tổ. Hiện còn ${remain} ảnh.`,true);templeFiles.value='';return;}for(const f of files){const url=URL.createObjectURL(f),wrap=document.createElement('div'),img=document.createElement('img');wrap.className='settings-temple-new-item';img.src=url;img.alt=f.name;img.dataset.objectUrl=url;wrap.appendChild(img);const name=document.createElement('small');name.textContent=f.name;wrap.appendChild(name);templeNew.appendChild(wrap);}});
