function auditDetailText(a){const raw=String(a?.detail||'').trim();if(!raw)return '—';if(a?.action==='settings.update'&&raw.startsWith('{'))return 'Cài đặt đã được sửa (bản ghi cũ).';return raw.length>700?raw.slice(0,700)+'…':raw;}
function renderAudit(){const {pageRows,start,totalRows,totalPages}=simplePage(S.audit,'auditPage');$('#auditTable').innerHTML=pageRows.length?pageRows.map((a,i)=>`<tr><td class="row-number">${start+i+1}</td><td>${time(a.created_at)}</td><td>${esc(a.display_name||a.username||'Hệ thống')}</td><td>${esc(actionLabel(a.action))}</td><td>${esc(a.entity_type)} ${a.entity_id?`· ${esc(String(a.entity_id).slice(0,12))}`:''}</td><td style="max-width:420px;white-space:normal;color:#777">${esc(auditDetailText(a))}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-row">Chưa có nhật ký.</td></tr>';renderSimplePagination('audit','auditPage',totalRows,totalPages,'nhật ký');}

function birthYear(value){const text=String(value||'');const matches=text.match(/\b(?:1[0-9]{3}|20[0-9]{2}|21[0-9]{2})\b/g);return matches?.[0]||'';}
function relationLabel(person){const year=birthYear(person?.birth_date);const branches=(person?.branch_names||[]).length?` · ${(person.branch_names||[]).join(' / ')}`:'';return `${person?.full_name||'Không rõ tên'} · ${year?`sinh ${year}`:'chưa rõ năm sinh'}${branches}`;}
function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('vi').trim();}
function relationPicker(label,name,selectedIds=[],gender='',multiple=false,kind='generic'){const ids=(Array.isArray(selectedIds)?selectedIds:[selectedIds]).filter(Boolean);const help=kind==='step-parent'?'Chọn cha/mẹ kế của cá thể. Đây là quan hệ Con riêng của vợ/chồng, khác với Con nuôi và không thay thế Cha/Mẹ huyết thống.':kind==='spouse'?'Có thể chọn nhiều vợ/chồng. Tách người đang là vợ/chồng và người đã ly hôn ở đúng hai mục; con riêng của từng cuộc hôn nhân được xác định bằng Cha/Mẹ của chính người con. Nếu hai người thuộc hai Chi khác nhau, hệ thống vẫn giữ cả hai Chi và đánh dấu hôn phối khác Chi.':multiple?'Có thể chọn nhiều người. Gõ tên hoặc năm sinh để lọc nhanh.':'Gõ họ tên hoặc năm sinh để tìm nhanh.';return `<div class="form-field relation-field"><label>${esc(label)}</label><div class="relation-picker" data-relation-name="${attr(name)}" data-multiple="${multiple?'1':'0'}" data-gender="${attr(gender)}" data-kind="${attr(kind)}" data-selected="${attr(JSON.stringify(ids))}"><div class="relation-selected"></div><input class="input relation-search" type="search" autocomplete="off" placeholder="Gõ họ tên hoặc năm sinh để tìm…"><div class="relation-options" hidden></div></div><small>${esc(help)}</small></div>`;}
function relationValues(name){const picker=$(`[data-relation-name="${name}"]`);if(!picker)return [];try{return JSON.parse(picker.dataset.selected||'[]');}catch{return [];}}
function setRelationValues(name,values){const picker=$(`[data-relation-name="${name}"]`);if(!picker)return;picker.dataset.selected=JSON.stringify([...new Set((values||[]).filter(Boolean))]);renderRelationSelection(picker);if(picker.dataset.kind==='spouse')syncSpouseOrderWithSelections();}
function orderedSpouseIdsForPerson(person){const ids=[...new Set((person?.spouse_ids||[]).filter(Boolean))],preferred=[...new Set((person?.spouse_order_ids||[]).filter(id=>ids.includes(id)))];return [...preferred,...ids.filter(id=>!preferred.includes(id))];}
function spouseOrderLabel(gender,index,total=1){if(total<=1)return gender==='male'?'Vợ':gender==='female'?'Chồng':'Phối ngẫu';if(gender==='male')return index===0?'Vợ cả':`Vợ ${index+1}`;if(gender==='female')return `Chồng ${index+1}`;return `Phối ngẫu ${index+1}`;}
function spouseOrderValues(){const host=$('#spouseOrderEditor');if(!host)return[];try{return JSON.parse(host.dataset.order||'[]');}catch{return[];}}
function syncSpouseOrderWithSelections(){const host=$('#spouseOrderEditor');if(!host)return;const selected=[...new Set([...relationValues('spouse_ids'),...relationValues('divorced_spouse_ids')])];let order=spouseOrderValues().filter(id=>selected.includes(id));for(const id of selected)if(!order.includes(id))order.push(id);host.dataset.order=JSON.stringify(order);renderSpouseOrderEditor();}
function moveSpouseOrder(id,delta){const host=$('#spouseOrderEditor');if(!host)return;const order=spouseOrderValues(),i=order.indexOf(id),j=i+delta;if(i<0||j<0||j>=order.length)return;[order[i],order[j]]=[order[j],order[i]];host.dataset.order=JSON.stringify(order);renderSpouseOrderEditor();}
function renderSpouseOrderEditor(){const host=$('#spouseOrderEditor');if(!host)return;const order=spouseOrderValues(),divorced=new Set(relationValues('divorced_spouse_ids')),gender=currentFormGender();if(!order.length){host.innerHTML='<div class="spouse-order-empty">Chưa chọn vợ/chồng.</div>';return;}host.innerHTML=order.map((id,index)=>{const p=S.people.find(x=>x.id===id);if(!p)return '';const status=divorced.has(id)?'Đã ly hôn':(p.is_deceased?'Đã mất':'Hiện tại');return `<div class="spouse-order-row"><span class="spouse-order-no">${esc(spouseOrderLabel(gender,index,order.length))}</span><span class="spouse-order-name"><strong>${esc(p.full_name)}</strong><small>${esc(status)}</small></span><span class="spouse-order-actions"><button type="button" data-spouse-order-up="${attr(id)}" ${index===0?'disabled':''} title="Đưa lên trước">↑</button><button type="button" data-spouse-order-down="${attr(id)}" ${index===order.length-1?'disabled':''} title="Đưa xuống sau">↓</button></span></div>`;}).join('');$$('[data-spouse-order-up]',host).forEach(b=>b.onclick=()=>moveSpouseOrder(b.dataset.spouseOrderUp,-1));$$('[data-spouse-order-down]',host).forEach(b=>b.onclick=()=>moveSpouseOrder(b.dataset.spouseOrderDown,1));}
function currentFormGender(){return $('#personForm [name="gender"]')?.value||'other';}
function oppositeGender(gender){return gender==='male'?'female':gender==='female'?'male':'';}
function selectedParentIds(){return [...relationValues('father_id'),...relationValues('mother_id')].filter(Boolean);}
function currentEditedPerson(){return S.editPersonId?S.people.find(p=>p.id===S.editPersonId):null;}
function estimateGeneration(){const parentIds=selectedParentIds();const parents=parentIds.map(id=>S.people.find(p=>p.id===id)).filter(Boolean);if(parents.length)return Math.min(50,Math.max(...parents.map(p=>Number(p.level)||1))+1);const spouseIds=[...new Set([...relationValues('spouse_ids'),...relationValues('divorced_spouse_ids')])];const spouses=spouseIds.map(id=>S.people.find(p=>p.id===id)).filter(Boolean);if(spouses.length)return Math.min(50,Math.max(...spouses.map(p=>Number(p.level)||1)));const current=currentEditedPerson();return current?Math.min(50,Math.max(1,Number(current.level)||1)):1;}
function spouseCandidateAllowed(person){const target=Math.min(50,Math.max(1,Number($('#personLevel')?.value)||estimateGeneration()));const parents=selectedParentIds();const current=currentEditedPerson();const spouseSelected=[...relationValues('spouse_ids'),...relationValues('divorced_spouse_ids')].length>0;const hasKnownParents=!!(person.father_id||person.mother_id);if(parents.length||spouseSelected||current){return Number(person.level||1)===target||!hasKnownParents;}return true;}
function relationCandidates(picker){const kind=picker.dataset.kind||'generic';let gender=picker.dataset.gender||'';if(kind==='spouse')gender=oppositeGender(currentFormGender());const name=picker.dataset.relationName;let selected=[];try{selected=JSON.parse(picker.dataset.selected||'[]');}catch{}const selectedSet=new Set(selected);const blocked=new Set();if(kind==='spouse'){for(const id of selectedParentIds())blocked.add(id);const counterpart=name==='spouse_ids'?'divorced_spouse_ids':'spouse_ids';for(const id of relationValues(counterpart))blocked.add(id);}const excludedId=picker.closest('#personForm')?S.editPersonId:null;return S.people.filter(p=>p.id!==excludedId&&!selectedSet.has(p.id)&&!blocked.has(p.id)&&(!gender||p.gender===gender)&&(kind!=='spouse'||spouseCandidateAllowed(p)));}
function initRelationPickers(){$$('.relation-picker').forEach(picker=>{renderRelationSelection(picker);const input=$('.relation-search',picker);const options=$('.relation-options',picker);const refresh=()=>renderRelationOptions(picker,input.value);input.addEventListener('focus',refresh);input.addEventListener('input',refresh);input.addEventListener('keydown',e=>{if(e.key==='Escape')options.hidden=true;});});const gender=$('#personForm [name="gender"]');if(gender)gender.addEventListener('change',()=>{syncSpouseSelectionsWithGender();refreshRelationPickers(true);});}
function renderRelationSelection(picker){let ids=[];try{ids=JSON.parse(picker.dataset.selected||'[]');}catch{}const selected=$('.relation-selected',picker);selected.innerHTML=ids.map(id=>{const p=S.people.find(x=>x.id===id);if(!p)return '';return `<span class="relation-chip">${esc(relationLabel(p))}<button type="button" data-remove-relation="${attr(id)}" aria-label="Bỏ lựa chọn">×</button></span>`;}).join('');selected.classList.toggle('empty',!ids.length);$$('[data-remove-relation]',selected).forEach(btn=>btn.onclick=()=>{const next=ids.filter(x=>x!==btn.dataset.removeRelation);picker.dataset.selected=JSON.stringify(next);renderRelationSelection(picker);if(picker.dataset.kind==='spouse')syncSpouseOrderWithSelections();updateGenerationPreview(['father_id','mother_id'].includes(picker.dataset.relationName));refreshRelationPickers(true);});}
function renderRelationOptions(picker,query=''){const q=normalizeSearch(query);const options=$('.relation-options',picker);const candidates=relationCandidates(picker).filter(p=>!q||normalizeSearch(`${p.full_name} ${p.birth_date||''} ${birthYear(p.birth_date)}`).includes(q)).sort((a,b)=>a.full_name.localeCompare(b.full_name,'vi')).slice(0,80);options.innerHTML=candidates.length?candidates.map(p=>`<button type="button" class="relation-option" data-relation-id="${attr(p.id)}"><strong>${esc(p.full_name)}</strong><span>${birthYear(p.birth_date)?`Sinh ${esc(birthYear(p.birth_date))}`:'Chưa rõ năm sinh'}${(p.branch_names||[]).length?` · ${esc((p.branch_names||[]).join(' / '))}`:''}</span></button>`).join(''):'<div class="relation-empty">Không tìm thấy cá thể phù hợp.</div>';options.hidden=false;$$('[data-relation-id]',options).forEach(btn=>btn.onclick=()=>{const id=btn.dataset.relationId;let ids=[];try{ids=JSON.parse(picker.dataset.selected||'[]');}catch{}const multiple=picker.dataset.multiple==='1';const next=multiple?[...ids,id]:[id];picker.dataset.selected=JSON.stringify([...new Set(next)]);if(picker.dataset.kind==='spouse'){const other=picker.dataset.relationName==='spouse_ids'?'divorced_spouse_ids':'spouse_ids';setRelationValues(other,relationValues(other).filter(x=>x!==id));}$('.relation-search',picker).value='';renderRelationSelection(picker);if(picker.dataset.kind==='spouse')syncSpouseOrderWithSelections();updateGenerationPreview(['father_id','mother_id'].includes(picker.dataset.relationName));refreshRelationPickers(true);if(!multiple)options.hidden=true;});}
function refreshRelationPickers(onlyOpen=false){$$('.relation-picker').forEach(picker=>{const options=$('.relation-options',picker);if(onlyOpen&&options.hidden)return;renderRelationOptions(picker,$('.relation-search',picker)?.value||'');});}
function syncSpouseSelectionsWithGender(){const expected=oppositeGender(currentFormGender());if(!expected)return;for(const name of ['spouse_ids','divorced_spouse_ids']){const kept=relationValues(name).filter(id=>S.people.find(p=>p.id===id)?.gender===expected);setRelationValues(name,kept);}updateGenerationPreview();}
function updateGenerationPreview(force=false){const input=$('#personLevel');if(!input)return;if(force||input.dataset.manual!=='1'){input.value=String(estimateGeneration());input.dataset.manual='0';}const note=$('#generationModeNote');if(note)note.textContent=input.dataset.manual==='1'?'Đang dùng đời nhập thủ công. Nếu chọn lại Cha/Mẹ, hệ thống sẽ tự tính lại.':'Tự động tính khi chọn Cha/Mẹ; bạn vẫn có thể nhập thủ công.';}
function personPrivacyDefault(p=null){const configured=String(S.settings?.living_default_privacy||'').trim();return p?.privacy_mode||(['public','limited','private'].includes(configured)?configured:'limited');}
function openPerson(id=null){S.editPersonId=id;const p=id?S.people.find(x=>x.id===id):null;const defaultPrivacy=personPrivacyDefault(p);const divorced=new Set(p?.divorced_spouse_ids||[]);const currentSpouses=(p?.spouse_ids||[]).filter(x=>!divorced.has(x));const spouseOrder=orderedSpouseIdsForPerson(p);$('#personModalTitle').textContent=p?'Sửa cá thể':'Thêm cá thể';$('#personFormFields').innerHTML=`
<div class="form-field"><label>Mã cá thể</label><input class="input" value="${attr(p?.family_code||'Hệ thống sẽ tự cấp khi lưu')}" disabled><small>Mã được hệ thống tự động gán và không cần nhập thủ công.</small></div>${f('Họ và tên *','full_name',p?.full_name||'','','required')}
<div class="form-field"><label>Giới tính *</label><select class="select" name="gender"><option value="male" ${p?.gender==='male'?'selected':''}>Nam</option><option value="female" ${p?.gender==='female'?'selected':''}>Nữ</option><option value="other" ${p?.gender==='other'?'selected':''}>Khác</option></select></div><div class="form-field"><label>Đời / thế hệ</label><input class="input" id="personLevel" name="level" type="number" min="1" max="50" step="1" value="${Number(p?.level)||1}"><small id="generationModeNote">Tự động tính khi chọn Cha/Mẹ; bạn vẫn có thể nhập thủ công. Khi đổi đời của một cá thể, các đời phía sau và phối ngẫu liên quan sẽ tự cập nhật.</small></div>
${f('Ngày/năm sinh','birth_date',p?.birth_date||'')}${f('Ngày/năm mất','death_date',p?.death_date||'')}
<div class="form-field"><label>Nơi sinh</label><textarea class="textarea place-textarea" name="birth_place" rows="3" maxlength="2000" placeholder="Có thể nhập nhiều dòng…">${esc(p?.birth_place||'')}</textarea></div><div class="form-field"><label>Nơi mất</label><textarea class="textarea place-textarea" name="death_place" rows="3" maxlength="2000" placeholder="Có thể nhập nhiều dòng…">${esc(p?.death_place||'')}</textarea></div>
${relationPicker('Cha','father_id',p?.father_id?[p.father_id]:[],'male',false,'parent')}${relationPicker('Mẹ','mother_id',p?.mother_id?[p.mother_id]:[],'female',false,'parent')}
${relationPicker('Vợ / chồng','spouse_ids',currentSpouses,'',true,'spouse')}${relationPicker('Vợ / chồng đã ly hôn','divorced_spouse_ids',p?.divorced_spouse_ids||[],'',true,'spouse')}
${relationPicker('Cha / mẹ kế · Con riêng','step_parent_ids',p?.step_parent_ids||[],'',true,'step-parent')}
<div class="form-field full spouse-order-field"><label>Thứ tự hôn phối</label><div id="spouseOrderEditor" class="spouse-order-editor" data-order="${attr(JSON.stringify(spouseOrder))}"></div><small>Dùng ↑ / ↓ để đặt Vợ cả, Vợ 2, Vợ 3… (hoặc thứ tự Chồng). Thứ tự này quyết định vị trí hôn phối và nhóm con trên cây, kể cả người phối ngẫu đã mất hoặc đã ly hôn.</small></div>
<div class="form-field full relationship-guide"><strong>Quan hệ nhiều hôn nhân / khác Chi</strong><small>Một cá thể có thể có nhiều vợ/chồng hiện tại hoặc trước đây. Với mỗi người con, hãy chọn đúng Cha và Mẹ tương ứng để cây tự nối con vào đúng cặp. Người thuộc Chi này kết hôn với người thuộc Chi khác không cần sao chép cá thể; hệ thống tự nhận diện theo Chi/nhánh đã tạo.</small></div>
<div class="form-field"><label>Vai trò trong gia phả</label><label class="check-row"><input type="checkbox" name="is_inlaw" id="personIsInlaw" ${p?.is_inlaw?'checked':''}> Dâu / Rể · không tính thứ tự con nội tộc</label><small>Khi bật, hệ thống không dùng “Con thứ mấy” cho cá thể này. Nếu đang quản lý cả dòng bên ngoại/bên thông gia, chỉ bật khi bạn thực sự muốn xem người này là Dâu/Rể trong cây hiện tại.</small></div><div class="form-field" id="birthOrderField"><label>Thứ tự sinh</label><input class="input" name="birth_order" type="number" min="1" max="50" value="${attr(p?.birth_order>0?p.birth_order:1)}"><small>Chỉ áp dụng cho con huyết thống / con nuôi trong nội tộc.</small></div>${f('Nghề nghiệp','occupation',p?.occupation||'')}
<div class="form-field"><label>Quyền riêng tư *</label><select class="select" name="privacy_mode"><option value="public" ${defaultPrivacy==='public'?'selected':''}>Công khai</option><option value="limited" ${defaultPrivacy==='limited'?'selected':''}>Giới hạn</option><option value="private" ${defaultPrivacy==='private'?'selected':''}>Riêng tư</option></select><small>Limited: ẩn ngày sinh, nơi chốn, nghề, ghi chú, nguồn và ảnh trên trang công khai. Private: chỉ giữ vị trí/quan hệ để cây không bị đứt.</small></div><div class="form-field"><label>Trạng thái</label><label class="check-row"><input type="checkbox" name="is_deceased" ${p?.is_deceased?'checked':''}> Đã mất</label><label class="check-row"><input type="checkbox" name="is_adopted" ${p?.is_adopted?'checked':''}> Con nuôi</label></div>
<div class="form-field full"><label>Tiểu sử / ghi chú</label><textarea class="textarea" name="details" rows="4" maxlength="6000">${esc(p?.details||'')}</textarea></div><div class="form-field full"><label>Nguồn & trích dẫn</label><textarea class="textarea" name="source_citations" rows="4" maxlength="8000" placeholder="Ví dụ: Giấy khai sinh số..., sổ hộ tịch..., phỏng vấn ông/bà..., URL hoặc tài liệu lưu trữ...">${esc(p?.source_citations||'')}</textarea><small>Ghi nguồn giúp kiểm chứng thông tin và xử lý dữ liệu mâu thuẫn.</small></div>
<div class="form-field full"><label>Ảnh chân dung (PNG/JPG/WEBP, tối đa 5 MB)</label><div style="display:flex;gap:12px;align-items:center"><img class="image-preview" id="personImagePreview" src="${attr(p?.image_url||`/assets/avatar-${p?.gender==='female'?'female':p?.gender==='male'?'male':'placeholder'}.svg`)}" alt=""><input class="input" id="personImage" type="file" accept="image/png,image/jpeg,image/webp"><label class="check-row"><input type="checkbox" id="removeImage"> Xóa ảnh hiện tại</label></div></div>`;openModal('personModal');initRelationPickers();syncSpouseOrderWithSelections();const inlaw=$('#personIsInlaw'),birthField=$('#birthOrderField');const syncInlaw=()=>{if(birthField)birthField.classList.toggle('hidden',!!inlaw?.checked);};inlaw?.addEventListener('change',syncInlaw);syncInlaw();const levelInput=$('#personLevel');if(levelInput){levelInput.dataset.manual=p?'1':'0';levelInput.addEventListener('input',()=>{levelInput.dataset.manual='1';updateGenerationPreview();});}if(!p)updateGenerationPreview(true);else{const note=$('#generationModeNote');if(note)note.textContent='Có thể sửa trực tiếp. Nếu chọn lại Cha/Mẹ, hệ thống sẽ tự tính đời theo cha/mẹ.';}}
async function savePerson(e){e.preventDefault();const st=$('#personFormStatus');st.textContent='';const form=new FormData(e.target);const body={};for(const [k,v] of form.entries())body[k]=v;body.is_deceased=form.has('is_deceased');body.is_adopted=form.has('is_adopted');body.is_inlaw=form.has('is_inlaw');body.level=Math.min(50,Math.max(1,Number(body.level)||1));body.birth_order=body.is_inlaw?0:(Number(body.birth_order)||1);body.father_id=relationValues('father_id')[0]||'';body.mother_id=relationValues('mother_id')[0]||'';const spouseIds=relationValues('spouse_ids');const divorcedIds=relationValues('divorced_spouse_ids');body.spouse_ids=[...new Set([...spouseIds,...divorcedIds])];body.spouse_order_ids=spouseOrderValues();body.divorced_spouse_ids=divorcedIds;body.step_parent_ids=relationValues('step_parent_ids');body.remove_image=$('#removeImage').checked;const file=$('#personImage').files[0];if(file)body.image_data=await readFileDataUrl(file);try{const url=S.editPersonId?`/api/admin/people/${S.editPersonId}`:'/api/admin/people';await api(url,{method:S.editPersonId?'PUT':'POST',body:JSON.stringify(body)});closeModal('personModal');toast(S.editPersonId?'Đã cập nhật cá thể.':'Đã thêm cá thể.');await Promise.all([loadPeople(),loadDashboard()]);}catch(err){st.textContent=err.message;}}

async function deletePerson(id){const p=S.people.find(x=>x.id===id);if(!confirm(`Xóa ${p?.full_name||'cá thể này'}? Các liên kết đến cá thể sẽ được gỡ khỏi cây.`))return;try{await api(`/api/admin/people/${id}`,{method:'DELETE'});toast('Đã xóa cá thể.');await Promise.all([loadPeople(),loadDashboard()]);}catch(e){toast(e.message,true);}}

function openBranch(id=null){
  S.editBranchId=id;const b=id?S.branches.find(x=>x.id===id):null;$('#branchModalTitle').textContent=b?'Sửa Chi gia phả':'Thêm Chi gia phả';
  $('#branchFormFields').innerHTML=`${f('Tên Chi *','name',b?.name||'','','required maxlength="120"')}${f('Thứ tự hiển thị','sort_order',b?.sort_order||0,'number','min="-9999" max="9999"')}${relationPicker('Cá thể gốc của Chi *','branch_root',b?.root_person_id?[b.root_person_id]:[],'',false,'branch')}<div class="form-field"><label>Hiển thị công khai</label><label class="check-row"><input type="checkbox" name="is_public" ${!b||b.is_public?'checked':''}> Cho phép người xem chọn Chi này ở trang công khai</label></div><div class="form-field full"><label>Mô tả Chi</label><textarea class="textarea" name="description" rows="4" maxlength="1200" placeholder="Ví dụ: Hậu duệ của ông Nguyễn Văn A, nhánh trưởng…">${esc(b?.description||'')}</textarea><small>Chi không sao chép dữ liệu. Thành viên được tính tự động từ người gốc, hậu duệ và vợ/chồng của hậu duệ.</small></div>`;
  openModal('branchModal');initRelationPickers();
}
async function saveBranch(e){e.preventDefault();const st=$('#branchFormStatus');st.textContent='';const fd=new FormData(e.target);const body=Object.fromEntries(fd.entries());body.root_person_id=relationValues('branch_root')[0]||'';body.is_public=fd.has('is_public');body.sort_order=Number(body.sort_order)||0;if(!body.root_person_id){st.textContent='Vui lòng chọn cá thể gốc của Chi.';return;}try{await api(S.editBranchId?`/api/admin/branches/${S.editBranchId}`:'/api/admin/branches',{method:S.editBranchId?'PUT':'POST',body:JSON.stringify(body)});closeModal('branchModal');toast(S.editBranchId?'Đã cập nhật Chi.':'Đã tạo Chi.');await Promise.all([loadBranches(),loadDashboard()]);}catch(err){st.textContent=err.message;}}
async function deleteBranch(id){const b=S.branches.find(x=>x.id===id);if(!confirm(`Xóa ${b?.name||'Chi này'}? Dữ liệu cá thể sẽ KHÔNG bị xóa.`))return;try{await api(`/api/admin/branches/${id}`,{method:'DELETE'});toast('Đã xóa Chi. Dữ liệu cá thể vẫn được giữ nguyên.');await Promise.all([loadBranches(),loadDashboard()]);}catch(e){toast(e.message,true);}}

function openUser(id=null){S.editUserId=id;const u=id?S.users.find(x=>x.id===id):null;$('#userModalTitle').textContent=u?'Sửa user':'Tạo user';$('#userFormFields').innerHTML=`${u?`<div class="form-field full"><label>Username</label><input class="input" value="${attr(u.username)}" disabled></div>`:f('Username *','username','','','required pattern="[A-Za-z0-9._-]{3,40}"')}${f('Tên hiển thị *','display_name',u?.display_name||'','','required')}<div class="form-field"><label>Role</label><select class="select" name="role"><option value="viewer" ${u?.role==='viewer'?'selected':''}>viewer · chỉ xem</option><option value="editor" ${u?.role==='editor'?'selected':''}>editor · CRUD cá thể</option><option value="admin" ${u?.role==='admin'?'selected':''}>admin · toàn quyền</option></select></div><div class="form-field"><label>${u?'Đặt lại mật khẩu':'Mật khẩu *'}</label><input class="input" name="password" type="password" ${u?'':'required'} minlength="12" autocomplete="new-password"><small>${u?'Để trống nếu không đổi.':'Ít nhất 12 ký tự.'}</small></div><div class="form-field full"><label class="check-row"><input type="checkbox" name="can_manage_gallery" ${(u?.role==='admin'||u?.can_manage_gallery)?'checked':''} ${u?.role==='admin'?'disabled':''}> Cho phép quản lý Thư viện ảnh</label><small>User được cấp quyền có thể tạo thư mục, tải ảnh và sửa nội dung nhưng không thể xóa. Chỉ admin được xóa ảnh/thư mục.</small></div>${u?`<div class="form-field full"><label class="check-row"><input type="checkbox" name="is_active" ${u.is_active?'checked':''}> Tài khoản đang hoạt động</label></div>`:''}`;openModal('userModal');}
async function saveUser(e){e.preventDefault();const st=$('#userFormStatus');st.textContent='';const fd=new FormData(e.target);const body=Object.fromEntries(fd.entries());if(S.editUserId)body.is_active=fd.has('is_active');body.can_manage_gallery=fd.has('can_manage_gallery')||body.role==='admin';if(!body.password)delete body.password;try{await api(S.editUserId?`/api/admin/users/${S.editUserId}`:'/api/admin/users',{method:S.editUserId?'PUT':'POST',body:JSON.stringify(body)});closeModal('userModal');toast(S.editUserId?'Đã cập nhật user.':'Đã tạo user.');await loadUsers();}catch(err){st.textContent=err.message;}}
async function deleteComment(id){if(!confirm('Xóa bình luận này khỏi trang công khai?'))return;try{await api(`/api/admin/comments/${id}`,{method:'DELETE'});toast('Đã xóa bình luận.');await Promise.all([loadComments(),loadDashboard()]);}catch(e){toast(e.message,true);}}
function backupPasswordLength(value){return Array.from(String(value||'')).length;}
function backupPasswordHeader(value){const bytes=new TextEncoder().encode(String(value||''));let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return btoa(binary);}
function previewBackupFile(){const file=$('#backupRestoreFile')?.files?.[0];const info=$('#backupFileInfo');if(!info)return;if(!file){info.textContent='Chưa chọn tệp · dung lượng tối đa 1 GB.';return;}const mb=file.size/1024/1024;info.textContent=`${file.name} · ${mb<1?(file.size/1024).toFixed(1)+' KB':mb>=1024?(mb/1024).toFixed(2)+' GB':mb.toFixed(2)+' MB'} · gói data mã hóa`;}
async function exportBackup(){const password=$('#backupExportPassword')?.value||'';const confirmPassword=$('#backupExportPasswordConfirm')?.value||'';const btn=$('#backupExportBtn');if(backupPasswordLength(password)<8){toast('Mật khẩu backup cần ít nhất 8 ký tự. Nên dùng từ 12 ký tự trở lên.',true);$('#backupExportPassword')?.focus();return;}if(password!==confirmPassword){toast('Hai lần nhập mật khẩu backup chưa khớp.',true);$('#backupExportPasswordConfirm')?.focus();return;}if(!confirm('Tạo bản sao lưu dữ liệu hệ thống?\n\nLưu ý: data/uploads/gallery KHÔNG nằm trong file .gpbak và cần được sao lưu riêng.\n\nHãy chắc chắn bạn đã lưu mật khẩu ở nơi an toàn.'))return;try{if(btn){btn.disabled=true;btn.textContent='Đang đóng gói…';}const res=await fetch('/api/admin/backup/export',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':S.csrf},body:JSON.stringify({password})});if(!res.ok){let d={};try{d=await res.json();}catch{}throw new Error(d.error||'Không thể tạo bản sao lưu.');}const blob=await res.blob();const cd=res.headers.get('Content-Disposition')||'';const m=cd.match(/filename="([^"]+)"/);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=m?.[1]||'gia-pha-data-backup.gpbak';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);if($('#backupExportPassword'))$('#backupExportPassword').value='';if($('#backupExportPasswordConfirm'))$('#backupExportPasswordConfirm').value='';toast('Đã tạo backup dữ liệu hệ thống. Thư mục Gallery không nằm trong file này và cần sao lưu riêng.');}catch(e){toast(e.message||'Không thể tạo bản sao lưu.',true);}finally{if(btn){btn.disabled=false;btn.textContent='↓ Tạo backup .gpbak';}}}
async function restoreBackup(){const file=$('#backupRestoreFile')?.files?.[0];const password=$('#backupRestorePassword')?.value||'';const btn=$('#backupRestoreBtn');if(!file){toast('Vui lòng chọn tệp backup .gpbak.',true);return;}if(file.size>1024*1024*1024){toast('Tệp backup lớn hơn giới hạn 1 GB.',true);return;}if(backupPasswordLength(password)<8){toast('Vui lòng nhập đúng mật khẩu của tệp backup.',true);$('#backupRestorePassword')?.focus();return;}if(!confirm(`Bạn sắp KHÔI PHỤC tệp ${file.name}.\n\nDữ liệu hệ thống sẽ được thay thế theo backup; thư mục data/uploads/gallery hiện tại được giữ nguyên. Bạn vẫn nên sao lưu cả file .gpbak và Gallery riêng trước khi tiếp tục.`))return;const phrase=prompt('Để xác nhận lần cuối, hãy nhập chính xác: KHOI PHUC');if(phrase!=='KHOI PHUC'){toast('Đã hủy khôi phục.');return;}try{if(btn){btn.disabled=true;btn.textContent='Đang giải mã & khôi phục…';}const res=await fetch('/api/admin/backup/restore',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':S.csrf,'X-Backup-Password-B64':backupPasswordHeader(password)},body:file});let result={};try{result=await res.json();}catch{}if(!res.ok)throw new Error(result.error||'Không thể khôi phục dữ liệu.');const sum=result.summary||{};toast(`Khôi phục hoàn tất: ${Number(sum.people||0)} cá thể, ${Number(sum.users||0)} tài khoản, ${Number(sum.uploads||0)} tệp trong uploads.`);if($('#backupRestorePassword'))$('#backupRestorePassword').value='';setTimeout(()=>location.reload(),1200);}catch(e){toast(e.message||'Không thể khôi phục dữ liệu.',true);}finally{if(btn){btn.disabled=false;btn.textContent='Khôi phục dữ liệu';}}}
async function saveSettings(){
  const titleSize=Math.min(64,Math.max(16,Number($('#set_tree_title_font_size').value)||28));
  const clanSize=Math.min(96,Math.max(28,Number($('#set_clan_name_font_size').value)||66));
  const subtitleTokens=richEditorTokens($('#treeSubtitleEditor'),8000);
  const treeFooterTokens=richEditorTokens($('#treeFooterEditor'),8000);
  const galleryIntroTokens=richEditorTokens($('#galleryIntroEditor'),8000);
  const galleryFooterTokens=richEditorTokens($('#galleryFooterEditor'),8000);
  const fundTokens=richEditorTokens($('#fundSupportEditor'),4000);
  const authorTokens=richEditorTokens($('#footerAuthorEditor'),8000);
  const contactIntroTokens=richEditorTokens($('#contactIntroEditor'),8000);
  const contactFooterTokens=richEditorTokens($('#contactFooterEditor'),8000);
  const contactAddressTokens=richEditorTokens($('#contactMapAddressEditor'),8000);
  const welcomePopupTokens=richEditorTokens($('#welcomePopupEditor'),12000);
  const body={
    tree_title:$('#set_tree_title').value.trim(),
    clan_name:$('#set_clan_name').value.trim(),
    tree_subtitle:richPlainText(subtitleTokens),
    tree_subtitle_content:JSON.stringify(subtitleTokens),
    tree_footer_content:JSON.stringify(treeFooterTokens),
    gallery_intro_content:JSON.stringify(galleryIntroTokens),
    gallery_footer_content:JSON.stringify(galleryFooterTokens),
    tree_title_font_size:String(titleSize),
    clan_name_font_size:String(Math.max(clanSize,titleSize+4)),
    tree_font:$('#set_tree_font').value,
    living_default_privacy:$('#set_living_default_privacy').value,
    public_comments_enabled:$('#set_public_comments_enabled').value,
    fund_support_enabled:$('#set_fund_support_enabled')?.value||'0',
    fund_support_content:JSON.stringify(fundTokens),
    footer_author_text:richPlainText(authorTokens),
    footer_author_content:JSON.stringify(authorTokens),
    footer_author_font:authorTokens[0]?.font||S.settings.footer_author_font||'system',
    contact_intro_content:JSON.stringify(contactIntroTokens),
    contact_footer_content:JSON.stringify(contactFooterTokens),
    contact_map_url:$('#set_contact_map_url')?.value.trim()||'',
    contact_map_address_content:JSON.stringify(contactAddressTokens),
    welcome_popup_enabled:$('#set_welcome_popup_enabled')?.value||'0',
    welcome_popup_content:JSON.stringify(welcomePopupTokens),
    contribution_top_count:$('#set_contribution_top_count')?.value||'10',
    remove_contact_temple_images:$$('[data-remove-temple-path]:checked').map(x=>x.dataset.removeTemplePath).filter(Boolean),
    remove_logo:!!$('#set_remove_logo')?.checked,
    remove_fund_qr:!!$('#set_remove_fund_qr')?.checked,
  };
  try{
    const file=$('#set_site_logo_file')?.files?.[0];if(file)body.logo_image_data=await readFileDataUrl(file);
    const qrFile=$('#set_fund_qr_file')?.files?.[0];if(qrFile)body.fund_qr_image_data=await readFileDataUrl(qrFile);
    const templeFiles=[...($('#set_contact_temple_files')?.files||[])];const remaining=settingPathArray(S.settings.contact_temple_image_paths,S.settings.contact_temple_image_path).filter(p=>!body.remove_contact_temple_images.includes(p)).length;if(remaining+templeFiles.length>10)throw new Error('Không gian thờ tự chỉ được tối đa 10 ảnh.');if(templeFiles.length)body.contact_temple_image_data_list=await Promise.all(templeFiles.map(readFileDataUrl));
    const d=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(body)});S.settings=d.settings;renderSettings();toast('Đã lưu cài đặt.');
  }catch(e){toast(e.message,true);}
}

function switchView(name){if(!name)return;if(name==='gallery'&&!(S.auth.user.role==='admin'||S.auth.user.can_manage_gallery))return;if(name==='contact'&&S.auth.user.role!=='admin')return;window.scrollTo(0,0);$$('.admin-view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const labels={dashboard:'Tổng quan',people:'Cá thể',branches:'Chi / nhánh gia phả',gallery:'Thư viện ảnh & Video',news:'Tin tức',contributions:'Phương Danh Công Đức',contact:'Liên hệ',comments:'Bình luận',users:'Người dùng',settings:'Cài đặt',audit:'Nhật ký'};$('#viewTitle').textContent=labels[name]||'Quản trị';requestAnimationFrame(()=>window.scrollTo(0,0));if(name==='branches')loadBranches();if(name==='news')loadNews();if(name==='contributions')loadContributions();if(name==='gallery')loadGallery();if(name==='contact'&&S.auth.user.role==='admin')loadContacts();if(name==='comments'&&S.auth.user.role==='admin')loadComments();if(name==='audit'&&S.auth.user.role==='admin')loadAudit();}
function openModal(id){$('#'+id).classList.add('open');}function closeModal(id){$('#'+id).classList.remove('open');}
async function api(url,opt={}){const headers={...(opt.headers||{})};if(opt.body)headers['Content-Type']='application/json';if(opt.csrf!==false&&['POST','PUT','PATCH','DELETE'].includes(opt.method||'GET'))headers['X-CSRF-Token']=S.csrf;const res=await fetch(url,{...opt,headers});let data={};try{data=await res.json();}catch{}if(res.status===401&&url!=='/api/auth/login'){showLogin();throw new Error('Phiên đăng nhập đã hết hạn.');}if(!res.ok)throw new Error(data.error||`Lỗi ${res.status}`);return data;}
async function downloadProtected(url){try{const res=await fetch(url,{headers:{'X-CSRF-Token':S.csrf}});if(!res.ok){let d={};try{d=await res.json();}catch{}throw new Error(d.error||'Không thể xuất dữ liệu.');}const blob=await res.blob();const cd=res.headers.get('Content-Disposition')||'';const m=cd.match(/filename="([^"]+)"/);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=m?.[1]||'gia-pha-export';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){toast(e.message,true);}}
function settingPathArray(value,legacy=''){let out=[];try{const parsed=JSON.parse(String(value||'[]'));if(Array.isArray(parsed))out=parsed.map(String).filter(Boolean);}catch{}if(!out.length&&legacy)out=[String(legacy)];return [...new Set(out)].slice(0,10);}
function field(label,id,value,type='text',full=false){return `<div class="form-field${full?' full':''}"><label>${esc(label)}</label><input class="input" id="set_${id}" value="${attr(value||'')}" type="${type}"></div>`;}function f(label,name,value,type='text',extra=''){return `<div class="form-field"><label>${esc(label)}</label><input class="input" name="${attr(name)}" value="${attr(value??'')}" type="${type||'text'}" ${extra}></div>`;}
function selectValue(html,value){return html.replace(`value="${String(value||'').replace(/["&<>]/g,'')}"`,`value="${String(value||'').replace(/["&<>]/g,'')}" selected`);}function selectMulti(html,values){let out=html;for(const v of values||[])out=out.replace(`value="${attr(v)}"`,`value="${attr(v)}" selected`);return out;}
function privacyLabel(v){return v==='public'?'Công khai':v==='limited'?'Giới hạn':'Riêng tư';}function actionLabel(v){const map={'person.create':'Thêm cá thể','person.update':'Sửa cá thể','person.delete':'Xóa cá thể','branch.create':'Tạo Chi','branch.update':'Sửa Chi','branch.delete':'Xóa Chi','user.create':'Tạo user','user.update':'Sửa user','comment.delete':'Xóa bình luận','settings.update':'Sửa cài đặt','auth.login':'Đăng nhập','auth.logout':'Đăng xuất','user.password_change':'Đổi mật khẩu','export.json':'Xuất JSON','backup.export':'Sao lưu đầy đủ','backup.restore':'Khôi phục dữ liệu','export.gedcom':'Xuất GEDCOM','gallery.album_create':'Tạo thư mục ảnh','gallery.album_update':'Sửa thư mục ảnh','gallery.album_delete':'Xóa thư mục ảnh','gallery.photo_create':'Thêm ảnh thư viện','gallery.photo_update':'Sửa ảnh thư viện','gallery.photo_delete':'Xóa ảnh thư viện','gallery.video_create':'Thêm video YouTube','gallery.video_update':'Sửa video YouTube','gallery.video_delete':'Xóa video YouTube','contact.create':'Thêm người liên hệ','contact.update':'Sửa người liên hệ','contact.delete':'Xóa người liên hệ','contribution.create':'Thêm phương danh công đức','contribution.update':'Sửa phương danh công đức','contribution.delete':'Xóa phương danh công đức','news.create':'Đăng tin tức','news.update':'Sửa tin tức','news.delete':'Xóa tin tức'};return map[v]||v;}
function money(v){return new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(v)||0);}function contributionDate(v){const m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:(v||'—');}
function toast(msg,error=false){const t=document.createElement('div');t.className=`toast${error?' error':''}`;t.textContent=msg;$('#toastStack').appendChild(t);setTimeout(()=>t.remove(),3200);}function time(v){const d=new Date(v);if(Number.isNaN(d.getTime()))return '—';return new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d);}function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}function attr(v){return esc(v);}function readFileDataUrl(file){return new Promise((resolve,reject)=>{if(file.size>5*1024*1024)return reject(new Error('Ảnh lớn hơn 5 MB.'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Không đọc được ảnh.'));r.readAsDataURL(file);});}
